    ('chateau-de-neuschwanstein', 'Château néo-romantique construit pour le roi Louis II de Bavière.', 'Il est souvent cité comme une source d''inspiration du château de La Belle au bois dormant de Disney.', array['Encyclopædia Britannica — Neuschwanstein Castle']::text[]),
    ('cathedrale-de-cologne', 'Cathédrale gothique commencée en 1248 et achevée en 1880.', 'Elle est inscrite au patrimoine mondial de l''UNESCO depuis 1996.', array['UNESCO — Cologne Cathedral']::text[]),
    ('pays-no', 'Pays nordique qui s''étire le long de la côte occidentale de la péninsule scandinave.', 'Au nord du cercle polaire, le soleil ne se couche pas pendant une partie de l''été.', array['Encyclopædia Britannica — Norway']::text[]),
