    ('pays-fj', 'Archipel du Pacifique Sud formé de plus de 300 îles.', 'Son équipe de rugby à sept a remporté l''or olympique en 2016, première médaille olympique du pays.', array['Encyclopædia Britannica — Fiji']::text[]),
    ('capitale-fj', 'Capitale des Fidji, port sur la côte sud-est de Viti Levu.', 'C''est l''une des plus grandes villes du Pacifique Sud insulaire.', array['Encyclopædia Britannica — Suva']::text[]),
    ('levuka', 'Ancien port colonial et première capitale des Fidji sous administration britannique.', 'Il est inscrit au patrimoine mondial de l''UNESCO depuis 2013.', array['UNESCO — Levuka Historical Port Town']::text[]),
    ('pays-ki', 'État insulaire du Pacifique formé d''atolls dispersés de part et d''autre de l''équateur.', 'Ses îles de la Ligne comptent parmi les premières terres habitées à passer au Nouvel An.', array['Encyclopædia Britannica — Kiribati']::text[]),
    ('capitale-ki', 'Capitale de Kiribati, sur l''atoll de Tarawa.', 'Tarawa a été le théâtre d''une bataille en 1943, pendant la guerre du Pacifique.', array['Encyclopædia Britannica — Tarawa']::text[]),
    ('iles-phoenix', 'Vaste aire marine protégée autour d''atolls isolés.', 'Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2010.', array['UNESCO — Phoenix Islands Protected Area']::text[]),
    ('pays-fm', 'Fédération de quatre États insulaires du Pacifique, officiellement les États fédérés de Micronésie.', 'Ses îles s''étendent sur environ 2 700 kilomètres d''ouest en est.', array['Encyclopædia Britannica — Micronesia']::text[]),
    ('capitale-fm', 'Capitale de la Micronésie, sur l''île de Pohnpei.', 'Elle a remplacé Kolonia comme capitale en 1989.', array['Encyclopædia Britannica — Palikir']::text[]),
    ('nan-madol', 'Cité de blocs de basalte bâtie sur des îlots artificiels.', 'Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2016.', array['UNESCO — Nan Madol: Ceremonial Centre of Eastern Micronesia']::text[]),
    ('pays-nr', 'Petite île corallienne du Pacifique, l''un des plus petits États du monde.', 'Son économie a longtemps reposé sur l''extraction du phosphate.', array['Encyclopædia Britannica — Nauru']::text[]),
    ('capitale-nr', 'Nauru n''a pas de capitale officielle ; le district de Yaren accueille le Parlement et l''administration.', 'Le pays ne compte que quelques milliers d''habitants.', array['Encyclopædia Britannica — Nauru']::text[]),
    ('plateau-de-topside', 'Plateau intérieur appelé « Topside », largement exploité pour son phosphate.', 'L''extraction a laissé un paysage de pitons de corail.', array['Encyclopædia Britannica — Nauru']::text[]),
    ('pays-nu', 'Île corallienne surélevée de Polynésie, librement associée à la Nouvelle-Zélande ; elle n''est pas membre de l''ONU.', 'Elle est surnommée « le rocher de Polynésie ».', array['Encyclopædia Britannica — Niue']::text[]),
    ('capitale-nu', 'Capitale de Niue, sur la côte ouest de l''île.', 'C''est l''une des plus petites capitales du monde par la population.', array['Encyclopædia Britannica — Alofi']::text[]),
    ('arches-de-talava', 'Arches de calcaire sculptées par la mer sur la côte rocheuse.', 'Elles font partie des nombreuses grottes et criques de l''île.', array['Encyclopædia Britannica — Niue']::text[]),
    ('pays-pw', 'Archipel de Micronésie à l''est des Philippines.', 'En 2009, le pays a créé l''un des premiers sanctuaires de requins au monde.', array['Encyclopædia Britannica — Palau']::text[]),
    ('capitale-pw', 'Capitale des Palaos depuis 2006, sur l''île de Babeldaob.', 'Elle a remplacé Koror, qui reste la plus grande ville du pays.', array['Encyclopædia Britannica — Ngerulmud']::text[]),
    ('rock-islands', 'Centaines d''îlots calcaires couverts de forêt, en forme de champignon.', 'Le lagon sud des Rock Islands est inscrit au patrimoine mondial de l''UNESCO depuis 2012.', array['UNESCO — Rock Islands Southern Lagoon']::text[]),
    ('pays-pg', 'Pays qui occupe la moitié orientale de l''île de Nouvelle-Guinée et de nombreuses îles.', 'On y parle plus de 800 langues, un record mondial.', array['Encyclopædia Britannica — Papua New Guinea']::text[]),
    ('capitale-pg', 'Capitale de la Papouasie-Nouvelle-Guinée, sur la côte sud-est.', 'C''est la plus grande ville du pays.', array['Encyclopædia Britannica — Port Moresby']::text[]),
    ('site-agricole-de-kuk', 'Zone humide où l''on a retrouvé des traces d''agriculture très anciennes.', 'Il est inscrit au patrimoine mondial de l''UNESCO depuis 2008.', array['UNESCO — Kuk Early Agricultural Site']::text[]),
    ('pays-ws', 'Archipel de Polynésie formé principalement des îles d''Upolu et de Savai''i.', 'Fin 2011, le pays a sauté une journée en changeant de côté de la ligne de changement de date.', array['Encyclopædia Britannica — Samoa']::text[]),
    ('capitale-ws', 'Capitale des Samoa, sur la côte nord d''Upolu.', 'L''écrivain Robert Louis Stevenson a vécu ses dernières années près de la ville.', array['Encyclopædia Britannica — Apia']::text[]),
    ('to-sua', 'Bassin naturel au fond d''un effondrement, relié à l''océan.', 'On y descend par une longue échelle de bois.', array['Encyclopædia Britannica — Samoa']::text[]),
    ('pays-to', 'Royaume de Polynésie formé de plus de 170 îles.', 'C''est la seule monarchie du Pacifique insulaire.', array['Encyclopædia Britannica — Tonga']::text[]),
    ('capitale-to', 'Capitale des Tonga, sur l''île de Tongatapu.', 'Le palais royal en bois blanc se dresse face à la mer.', array['Encyclopædia Britannica — Nuku''alofa']::text[]),
    ('haamonga-a-maui', 'Trilithe de corail formé de deux piliers et d''un linteau.', 'Il aurait été érigé vers le XIIIe siècle.', array['Encyclopædia Britannica — Tonga']::text[]),
    ('pays-tv', 'Archipel de neuf îles basses de Polynésie.', 'Ses terres ne dépassent guère quelques mètres d''altitude, ce qui le rend très exposé à la montée des eaux.', array['Encyclopædia Britannica — Tuvalu']::text[]),
    ('capitale-tv', 'Capitale de Tuvalu, sur l''atoll du même nom.', 'La piste de l''aéroport occupe une grande partie de l''île principale.', array['Encyclopædia Britannica — Funafuti']::text[]),
    ('lagon-de-funafuti', 'Vaste lagon bordé d''îlots, dont une partie est classée en aire de conservation.', 'Il abrite tortues, poissons de récif et oiseaux marins.', array['Encyclopædia Britannica — Tuvalu']::text[]),
    ('pays-vu', 'Archipel de Mélanésie formé de plus de 80 îles.', 'Le français, l''anglais et le bichelamar y sont langues officielles.', array['Encyclopædia Britannica — Vanuatu']::text[]),
    ('capitale-vu', 'Capitale du Vanuatu, sur l''île d''Efate.', 'Elle est située au bord d''une baie abritée.', array['Encyclopædia Britannica — Port-Vila']::text[]),
    ('domaine-du-chef-roi-mata', 'Ensemble de sites liés à la vie et à la sépulture d''un chef du début du XVIIe siècle.', 'Il est inscrit au patrimoine mondial de l''UNESCO depuis 2008.', array['UNESCO — Chief Roi Mata''s Domain']::text[]),
    ('saut-du-gaul', 'Rituel où des hommes s''élancent de hautes tours, des lianes attachées aux chevilles.', 'Cette pratique est souvent citée comme l''ancêtre du saut à l''élastique.', array['Encyclopædia Britannica — Pentecost Island']::text[]),
    ('pays-ck', 'Archipel de Polynésie librement associé à la Nouvelle-Zélande ; il n''est pas membre de l''ONU.', 'Ses habitants possèdent la nationalité néo-zélandaise.', array['Encyclopædia Britannica — Cook Islands']::text[]),
    ('capitale-ck', 'Capitale des îles Cook, sur la côte nord de Rarotonga.', 'C''est le principal centre administratif et commercial de l''archipel.', array['Encyclopædia Britannica — Avarua']::text[]),
    ('lagon-d-aitutaki', 'Lagon turquoise parsemé d''îlots, entouré d''une barrière de corail.', 'Une petite île volcanique domine ce lagon fermé par un récif corallien.', array['Encyclopædia Britannica — Aitutaki']::text[]),
    ('pays-mh', 'Archipel de Micronésie formé de deux chaînes d''atolls coralliens.', 'Le pays est associé aux États-Unis par un accord de libre association.', array['Encyclopædia Britannica — Marshall Islands']::text[]),
    ('capitale-mh', 'Capitale des îles Marshall, située sur l''atoll du même nom.', 'La ville s''étire sur une étroite bande de terre entre l''océan et le lagon.', array['Encyclopædia Britannica — Majuro']::text[]),
    ('atoll-de-bikini', 'Atoll où les États-Unis ont mené des essais nucléaires de 1946 à 1958.', 'Il est inscrit au patrimoine mondial de l''UNESCO depuis 2010.', array['UNESCO — Bikini Atoll Nuclear Test Site']::text[]),
    ('pays-sb', 'Archipel de Mélanésie formé de près d''un millier d''îles.', 'Il a été le théâtre de la bataille de Guadalcanal en 1942-1943.', array['Encyclopædia Britannica — Solomon Islands']::text[]),
    ('capitale-sb', 'Capitale des îles Salomon, sur l''île de Guadalcanal.', 'La ville s''est développée après la Seconde Guerre mondiale.', array['Encyclopædia Britannica — Honiara']::text[]),
    ('rennell-est', 'Partie orientale d''un atoll surélevé abritant le lac Tegano.', 'Elle est inscrite au patrimoine mondial de l''UNESCO depuis 1998.', array['UNESCO — East Rennell']::text[])
  ) as v (slug, discovery_text, fun_fact, sources)
  join public.cards c on c.slug = v.slug
on conflict (card_id) do update set
  discovery_text = excluded.discovery_text, fun_fact = excluded.fun_fact, sources = excluded.sources;

insert into public.collections (slug, title, description, collection_type, continent, status, position) values
  ('pays-afrique', 'Pays d''Afrique', 'Les cartes Pays du continent africain.', 'geographic', 'africa', 'published', 1),
  ('pays-amerique-du-nord', 'Pays d''Amérique du Nord', 'Les cartes Pays d''Amérique du Nord et d''Amérique centrale.', 'geographic', 'north_america', 'published', 2),
  ('pays-amerique-du-sud', 'Pays d''Amérique du Sud', 'Les cartes Pays d''Amérique du Sud.', 'geographic', 'south_america', 'published', 3),
  ('pays-asie', 'Pays d''Asie', 'Les cartes Pays du continent asiatique.', 'geographic', 'asia', 'published', 4),
  ('pays-europe', 'Pays d''Europe', 'Les cartes Pays du continent européen.', 'geographic', 'europe', 'published', 5),
  ('pays-oceanie', 'Pays d''Océanie', 'Les cartes Pays d''Océanie.', 'geographic', 'oceania', 'published', 6),
  ('capitales-du-monde', 'Capitales du monde', 'Toutes les capitales du catalogue.', 'geographic', null, 'published', 7),
  ('patrimoine-bati', 'Patrimoine bâti', 'Monuments et sites construits par les sociétés humaines.', 'cultural', null, 'published', 8),
  ('paysages-remarquables', 'Paysages remarquables', 'Reliefs, côtes et milieux naturels d''exception.', 'thematic', null, 'published', 9),
  ('cultures-et-memoires', 'Cultures et mémoires', 'Langues, traditions et lieux de mémoire.', 'cultural', null, 'published', 10)
on conflict (slug) do update set
  title = excluded.title, description = excluded.description, collection_type = excluded.collection_type,
  continent = excluded.continent, status = excluded.status, position = excluded.position;

delete from public.collection_cards
 where collection_id in (select id from public.collections where slug in ('pays-afrique', 'pays-amerique-du-nord', 'pays-amerique-du-sud', 'pays-asie', 'pays-europe', 'pays-oceanie', 'capitales-du-monde', 'patrimoine-bati', 'paysages-remarquables', 'cultures-et-memoires'));

