    ('expedition-nl', 3, 'quiz', 'Défi de connaissances', 'Dans quelle ville siège le gouvernement néerlandais ?', null, array['Amsterdam', 'Rotterdam', 'La Haye', 'Utrecht']::text[], 'Amsterdam est la capitale, mais le gouvernement siège à La Haye.', 2),
    ('expedition-pl', 1, 'locate', 'Situer la Pologne', 'La Pologne se trouve en Europe (Europe centrale). Quelle est sa capitale ?', null, array['Varsovie', 'Amsterdam', 'Andorre-la-Vieille', 'Athènes']::text[], 'Varsovie est la capitale de la Pologne.', 0),
    ('expedition-pl', 2, 'discover', 'Découvrir : Mine de sel de Wieliczka', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Mine de sel exploitée pendant des siècles, aux chapelles sculptées dans le sel. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 1978.', null, 'Mine de sel de Wieliczka fait désormais partie de ton carnet de route.', null),
    ('expedition-pl', 3, 'quiz', 'Défi de connaissances', 'Quelle scientifique célèbre est née en Pologne ?', null, array['Marie Curie', 'Ada Lovelace', 'Rosalind Franklin', 'Lise Meitner']::text[], 'Marie Curie est née à Varsovie en 1867.', 0),
    ('expedition-pt', 1, 'locate', 'Situer le Portugal', 'Le Portugal se trouve en Europe (Europe du Sud). Quelle est sa capitale ?', null, array['Lisbonne', 'Amsterdam', 'Andorre-la-Vieille', 'Athènes']::text[], 'Lisbonne est la capitale du Portugal.', 0),
    ('expedition-pt', 2, 'discover', 'Découvrir : Tour de Belém', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Tour fortifiée du XVIe siècle à l''entrée du port de Lisbonne. Elle est inscrite au patrimoine mondial de l''UNESCO avec le monastère des Hiéronymites.', null, 'Tour de Belém fait désormais partie de ton carnet de route.', null),
    ('expedition-pt', 3, 'quiz', 'Défi de connaissances', 'Quel est le point le plus occidental de l''Europe continentale ?', null, array['Le cap da Roca', 'Le cap Finisterre', 'La pointe du Raz', 'Le cap Nord']::text[], 'Le cap da Roca se trouve au Portugal.', 0),
    ('expedition-ro', 1, 'locate', 'Situer la Roumanie', 'La Roumanie se trouve en Europe (Europe de l''Est). Quelle est sa capitale ?', null, array['Amsterdam', 'Bucarest', 'Andorre-la-Vieille', 'Athènes']::text[], 'Bucarest est la capitale de la Roumanie.', 1),
    ('expedition-ro', 2, 'discover', 'Découvrir : Delta du Danube', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Immense zone humide de bras, de lacs et de roselières. Il est inscrit au patrimoine mondial de l''UNESCO depuis 1991.', null, 'Delta du Danube fait désormais partie de ton carnet de route.', null),
    ('expedition-ro', 3, 'quiz', 'Défi de connaissances', 'Quelle chaîne de montagnes traverse la Roumanie ?', null, array['Les Alpes', 'Les Carpates', 'Les Pyrénées', 'Les Apennins']::text[], 'L''arc des Carpates traverse le pays.', 1),
    ('expedition-gb', 1, 'locate', 'Situer le Royaume-Uni', 'Le Royaume-Uni se trouve en Europe (Europe du Nord). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Athènes', 'Londres']::text[], 'Londres est la capitale du Royaume-Uni.', 3),
    ('expedition-gb', 2, 'discover', 'Découvrir : Stonehenge', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cercle de pierres dressées préhistorique. Ses pierres sont alignées sur les levers et couchers du soleil aux solstices.', null, 'Stonehenge fait désormais partie de ton carnet de route.', null),
    ('expedition-gb', 3, 'quiz', 'Défi de connaissances', 'Quelles nations forment le Royaume-Uni ?', null, array['Angleterre, Écosse, Irlande', 'Angleterre et Écosse seulement', 'Angleterre, pays de Galles, Cornouailles', 'Angleterre, Écosse, pays de Galles, Irlande du Nord']::text[], 'Le Royaume-Uni réunit quatre nations.', 3),
    ('expedition-ru', 1, 'locate', 'Situer la Russie', 'La Russie se trouve en Europe (Europe de l''Est). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Athènes', 'Moscou']::text[], 'Moscou est la capitale de la Russie.', 3),
    ('expedition-ru', 2, 'discover', 'Découvrir : Lac Baïkal', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Lac de Sibérie méridionale entouré de montagnes. C''est le lac le plus profond du monde, avec plus de 1 600 mètres.', null, 'Lac Baïkal fait désormais partie de ton carnet de route.', null),
    ('expedition-ru', 3, 'quiz', 'Défi de connaissances', 'Combien de fuseaux horaires couvre la Russie ?', null, array['Cinq', 'Huit', 'Quatorze', 'Onze']::text[], 'La Russie s''étend sur onze fuseaux horaires.', 3),
    ('expedition-sm', 1, 'locate', 'Situer Saint-Marin', 'Saint-Marin se trouve en Europe (Europe du Sud). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Saint-Marin', 'Athènes']::text[], 'Saint-Marin est la capitale de Saint-Marin.', 2),
    ('expedition-sm', 2, 'discover', 'Découvrir : Mont Titano', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Mont couronné de trois tours médiévales dominant la région. Le centre historique et le mont Titano sont inscrits au patrimoine mondial de l''UNESCO.', null, 'Mont Titano fait désormais partie de ton carnet de route.', null),
    ('expedition-sm', 3, 'quiz', 'Défi de connaissances', 'Dans quel pays Saint-Marin est-il enclavé ?', null, array['La France', 'La Suisse', 'L''Italie', 'L''Autriche']::text[], 'Saint-Marin est entièrement entouré par l''Italie.', 2),
    ('expedition-rs', 1, 'locate', 'Situer la Serbie', 'La Serbie se trouve en Europe (Europe du Sud). Quelle est sa capitale ?', null, array['Amsterdam', 'Belgrade', 'Andorre-la-Vieille', 'Athènes']::text[], 'Belgrade est la capitale de la Serbie.', 1),
    ('expedition-rs', 2, 'discover', 'Découvrir : Monastère de Studenica', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Monastère orthodoxe fondé à la fin du XIIe siècle, aux églises de marbre blanc. Il est inscrit au patrimoine mondial de l''UNESCO depuis 1986.', null, 'Monastère de Studenica fait désormais partie de ton carnet de route.', null),
    ('expedition-rs', 3, 'quiz', 'Défi de connaissances', 'Au confluent de quels cours d''eau se trouve Belgrade ?', null, array['Le Rhin et le Main', 'La Save et le Danube', 'La Drina et la Morava', 'Le Danube et la Tisza']::text[], 'Belgrade est bâtie au confluent de la Save et du Danube.', 1),
    ('expedition-sk', 1, 'locate', 'Situer la Slovaquie', 'La Slovaquie se trouve en Europe (Europe centrale). Quelle est sa capitale ?', null, array['Bratislava', 'Amsterdam', 'Andorre-la-Vieille', 'Athènes']::text[], 'Bratislava est la capitale de la Slovaquie.', 0),
    ('expedition-sk', 2, 'discover', 'Découvrir : Château de Spiš', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ruines d''un château médiéval perché sur une colline. C''est l''un des plus grands ensembles castraux d''Europe centrale.', null, 'Château de Spiš fait désormais partie de ton carnet de route.', null),
    ('expedition-sk', 3, 'quiz', 'Défi de connaissances', 'De quel pays la Slovaquie s''est-elle séparée en 1993 ?', null, array['La Tchécoslovaquie', 'La Yougoslavie', 'L''Autriche-Hongrie', 'L''Union soviétique']::text[], 'La Tchécoslovaquie s''est scindée en Tchéquie et en Slovaquie en 1993.', 0),
    ('expedition-si', 1, 'locate', 'Situer la Slovénie', 'La Slovénie se trouve en Europe (Europe centrale). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Ljubljana', 'Athènes']::text[], 'Ljubljana est la capitale de la Slovénie.', 2),
    ('expedition-si', 2, 'discover', 'Découvrir : Grottes de Škocjan', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Réseau de grottes calcaires creusées par une rivière souterraine. Elles sont inscrites au patrimoine mondial de l''UNESCO depuis 1986.', null, 'Grottes de Škocjan fait désormais partie de ton carnet de route.', null),
    ('expedition-si', 3, 'quiz', 'Défi de connaissances', 'Quel animal est l''emblème de Ljubljana ?', null, array['L''ours', 'L''aigle', 'Le dragon', 'Le lion']::text[], 'Le dragon figure sur les armoiries de la ville.', 2),
    ('expedition-ch', 1, 'locate', 'Situer la Suisse', 'La Suisse se trouve en Europe (Europe centrale). Quelle est sa capitale ?', null, array['Amsterdam', 'Berne', 'Andorre-la-Vieille', 'Athènes']::text[], 'Berne est la capitale de la Suisse.', 1),
    ('expedition-ch', 2, 'discover', 'Découvrir : Cervin', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Sommet pyramidal des Alpes à la frontière italo-suisse. Il culmine à 4 478 mètres.', null, 'Cervin fait désormais partie de ton carnet de route.', null),
    ('expedition-ch', 3, 'quiz', 'Défi de connaissances', 'Combien de langues nationales compte la Suisse ?', null, array['Deux', 'Quatre', 'Trois', 'Cinq']::text[], 'L''allemand, le français, l''italien et le romanche sont langues nationales.', 1),
    ('expedition-se', 1, 'locate', 'Situer la Suède', 'La Suède se trouve en Europe (Europe du Nord). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Stockholm', 'Athènes']::text[], 'Stockholm est la capitale de la Suède.', 2),
    ('expedition-se', 2, 'discover', 'Découvrir : Vasa', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Navire de guerre qui a sombré lors de son voyage inaugural en 1628. Renfloué en 1961, il est exposé dans un musée de Stockholm.', null, 'Vasa fait désormais partie de ton carnet de route.', null),
    ('expedition-se', 3, 'quiz', 'Défi de connaissances', 'De quel inventeur suédois les prix Nobel portent-ils le nom ?', null, array['Anders Celsius', 'Carl von Linné', 'Alfred Nobel', 'Ingvar Kamprad']::text[], 'Alfred Nobel a légué sa fortune pour créer les prix.', 2),
    ('expedition-cz', 1, 'locate', 'Situer la Tchéquie', 'La Tchéquie se trouve en Europe (Europe centrale). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Athènes', 'Prague']::text[], 'Prague est la capitale de la Tchéquie.', 3),
    ('expedition-cz', 2, 'discover', 'Découvrir : Pont Charles', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Pont de pierre du XIVe siècle orné de statues baroques. Sa construction a commencé sous l''empereur Charles IV.', null, 'Pont Charles fait désormais partie de ton carnet de route.', null),
    ('expedition-cz', 3, 'quiz', 'Défi de connaissances', 'Quel fleuve traverse Prague ?', null, array['Le Danube', 'L''Elbe', 'L''Oder', 'La Vltava']::text[], 'Prague est bâtie sur les rives de la Vltava.', 3),
    ('expedition-ua', 1, 'locate', 'Situer l''Ukraine', 'L''Ukraine se trouve en Europe (Europe de l''Est). Quelle est sa capitale ?', null, array['Kyiv', 'Amsterdam', 'Andorre-la-Vieille', 'Athènes']::text[], 'Kyiv est la capitale de l''Ukraine.', 0),
    ('expedition-ua', 2, 'discover', 'Découvrir : Cathédrale Sainte-Sophie', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cathédrale du XIe siècle aux coupoles dorées et aux mosaïques byzantines. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 1990.', null, 'Cathédrale Sainte-Sophie fait désormais partie de ton carnet de route.', null),
    ('expedition-ua', 3, 'quiz', 'Défi de connaissances', 'Quel fleuve traverse Kyiv ?', null, array['Le Dniepr', 'Le Danube', 'La Volga', 'Le Don']::text[], 'Kyiv est bâtie sur les rives du Dniepr.', 0),
    ('expedition-va', 1, 'locate', 'Situer le Vatican', 'Le Vatican se trouve en Europe (Europe du Sud). Quelle est sa capitale ?', null, array['Amsterdam', 'Andorre-la-Vieille', 'Athènes', 'Cité du Vatican']::text[], 'Cité du Vatican est la capitale du Vatican.', 3),
    ('expedition-va', 2, 'discover', 'Découvrir : Chapelle Sixtine', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Chapelle du palais apostolique où se réunit le conclave. Michel-Ange en a peint la voûte entre 1508 et 1512.', null, 'Chapelle Sixtine fait désormais partie de ton carnet de route.', null),
    ('expedition-va', 3, 'quiz', 'Défi de connaissances', 'Qui a peint la voûte de la chapelle Sixtine ?', null, array['Raphaël', 'Léonard de Vinci', 'Botticelli', 'Michel-Ange']::text[], 'Michel-Ange a peint la voûte entre 1508 et 1512.', 3),
    ('expedition-af', 1, 'locate', 'Situer l''Afghanistan', 'L''Afghanistan se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Kaboul', 'Achgabat', 'Amman']::text[], 'Kaboul est la capitale de l''Afghanistan.', 1),
    ('expedition-af', 2, 'discover', 'Découvrir : Vallée de Bamiyan', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vallée de l''Hindou Kouch dont les falaises abritaient deux bouddhas géants taillés dans la roche. Les statues ont été détruites en 2001 ; le site est inscrit au patrimoine mondial de l''UNESCO.', null, 'Vallée de Bamiyan fait désormais partie de ton carnet de route.', null),
    ('expedition-af', 3, 'quiz', 'Défi de connaissances', 'Quelle chaîne de montagnes traverse l''Afghanistan ?', null, array['L''Atlas', 'L''Hindou Kouch', 'L''Oural', 'Le Caucase']::text[], 'L''Hindou Kouch traverse l''Afghanistan du nord-est au centre.', 1),
    ('expedition-sa', 1, 'locate', 'Situer l''Arabie saoudite', 'L''Arabie saoudite se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Riyad', 'Amman']::text[], 'Riyad est la capitale de l''Arabie saoudite.', 2),
    ('expedition-sa', 2, 'discover', 'Découvrir : Hégra', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Site nabatéen aux tombeaux monumentaux taillés dans le grès. C''est le premier site saoudien inscrit au patrimoine mondial de l''UNESCO, en 2008.', null, 'Hégra fait désormais partie de ton carnet de route.', null),
    ('expedition-sa', 3, 'quiz', 'Défi de connaissances', 'Quel peuple a taillé les tombeaux d''Hégra ?', null, array['Les Romains', 'Les Perses', 'Les Nabatéens', 'Les Ottomans']::text[], 'Hégra était une cité nabatéenne, comme Pétra en Jordanie.', 2),
    ('expedition-am', 1, 'locate', 'Situer l''Arménie', 'L''Arménie se trouve en Asie (Caucase). Quelle est sa capitale ?', null, array['Erevan', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Erevan est la capitale de l''Arménie.', 0),
    ('expedition-am', 2, 'discover', 'Découvrir : Monastère de Guéghard', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Monastère médiéval dont plusieurs églises sont creusées dans la roche. Il est inscrit au patrimoine mondial de l''UNESCO avec la haute vallée de l''Azat.', null, 'Monastère de Guéghard fait désormais partie de ton carnet de route.', null),
    ('expedition-am', 3, 'quiz', 'Défi de connaissances', 'Quelle montagne, située en Turquie, est visible depuis Erevan ?', null, array['Le mont Ararat', 'L''Elbrouz', 'Le Kazbek', 'Le mont Damavand']::text[], 'Le mont Ararat domine l''horizon d''Erevan par temps clair.', 0),
    ('expedition-az', 1, 'locate', 'Situer l''Azerbaïdjan', 'L''Azerbaïdjan se trouve en Asie (Caucase). Quelle est sa capitale ?', null, array['Abou Dabi', 'Bakou', 'Achgabat', 'Amman']::text[], 'Bakou est la capitale de l''Azerbaïdjan.', 1),
    ('expedition-az', 2, 'discover', 'Découvrir : Vieille ville de Bakou', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cité fortifiée qui abrite le palais des Chirvanchahs et la tour de la Vierge. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2000.', null, 'Vieille ville de Bakou fait désormais partie de ton carnet de route.', null),
    ('expedition-az', 3, 'quiz', 'Défi de connaissances', 'Quel est le surnom de l''Azerbaïdjan ?', null, array['Le pays des mille lacs', 'Le pays du feu', 'Le pays du matin calme', 'Le pays des aigles']::text[], 'Ses émanations de gaz enflammé lui valent le surnom de « pays du feu ».', 1),
    ('expedition-bh', 1, 'locate', 'Situer Bahreïn', 'Bahreïn se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Manama', 'Amman']::text[], 'Manama est la capitale de Bahreïn.', 2),
    ('expedition-bh', 2, 'discover', 'Découvrir : Qal''at al-Bahreïn', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Tell archéologique surmonté d''un fort, ancien port de la civilisation de Dilmun. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2005.', null, 'Qal''at al-Bahreïn fait désormais partie de ton carnet de route.', null),
    ('expedition-bh', 3, 'quiz', 'Défi de connaissances', 'À quel pays Bahreïn est-il relié par une chaussée ?', null, array['Le Qatar', 'L''Iran', 'L''Arabie saoudite', 'Le Koweït']::text[], 'La chaussée du roi Fahd relie Bahreïn à l''Arabie saoudite.', 2),
    ('expedition-bd', 1, 'locate', 'Situer le Bangladesh', 'Le Bangladesh se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Dacca', 'Amman']::text[], 'Dacca est la capitale du Bangladesh.', 2),
    ('expedition-bd', 2, 'discover', 'Découvrir : Sundarbans', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Immense forêt de mangrove partagée entre le Bangladesh et l''Inde. Elle abrite des tigres du Bengale et est inscrite au patrimoine mondial de l''UNESCO.', null, 'Sundarbans fait désormais partie de ton carnet de route.', null),
    ('expedition-bd', 3, 'quiz', 'Défi de connaissances', 'Quel félin habite la mangrove des Sundarbans ?', null, array['Le lion d''Asie', 'Le léopard des neiges', 'Le tigre du Bengale', 'Le guépard']::text[], 'Les Sundarbans abritent une population de tigres du Bengale.', 2),
    ('expedition-bt', 1, 'locate', 'Situer le Bhoutan', 'Le Bhoutan se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Thimphou', 'Amman']::text[], 'Thimphou est la capitale du Bhoutan.', 2),
    ('expedition-bt', 2, 'discover', 'Découvrir : Monastère de Taktshang', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Monastère bouddhiste accroché à une falaise, surnommé « le nid du tigre ». Selon la tradition, Padmasambhava y serait arrivé sur le dos d''une tigresse.', null, 'Monastère de Taktshang fait désormais partie de ton carnet de route.', null),
    ('expedition-bt', 3, 'quiz', 'Défi de connaissances', 'Quel indice le Bhoutan utilise-t-il pour mesurer son développement ?', null, array['Le produit intérieur net', 'L''indice de liberté', 'Le bonheur national brut', 'Le revenu moyen']::text[], 'Le Bhoutan a fait du « bonheur national brut » un principe de gouvernement.', 2),
    ('expedition-mm', 1, 'locate', 'Situer la Birmanie', 'La Birmanie se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Naypyidaw', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Naypyidaw est la capitale de la Birmanie.', 0),
    ('expedition-mm', 2, 'discover', 'Découvrir : Bagan', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Plaine couverte de milliers de temples et de stupas bouddhistes au bord de l''Irrawaddy. Le site est inscrit au patrimoine mondial de l''UNESCO depuis 2019.', null, 'Bagan fait désormais partie de ton carnet de route.', null),
    ('expedition-mm', 3, 'quiz', 'Défi de connaissances', 'Quel autre nom porte la Birmanie ?', null, array['Myanmar', 'Siam', 'Ceylan', 'Cathay']::text[], 'Le pays est aussi appelé Myanmar, nom officiel depuis 1989.', 0),
    ('expedition-bn', 1, 'locate', 'Situer le Brunei', 'Le Brunei se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Bandar Seri Begawan', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Bandar Seri Begawan est la capitale du Brunei.', 0),
    ('expedition-bn', 2, 'discover', 'Découvrir : Mosquée Omar Ali Saifuddien', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Mosquée à coupole dorée achevée en 1958, au bord d''un lagon artificiel. Elle porte le nom du 28e sultan du Brunei.', null, 'Mosquée Omar Ali Saifuddien fait désormais partie de ton carnet de route.', null),
    ('expedition-bn', 3, 'quiz', 'Défi de connaissances', 'Sur quelle île se trouve le Brunei ?', null, array['Bornéo', 'Sumatra', 'Java', 'Luçon']::text[], 'Le Brunei est situé sur la côte nord de Bornéo.', 0),
    ('expedition-kp', 1, 'locate', 'Situer la Corée du Nord', 'La Corée du Nord se trouve en Asie (Asie de l''Est). Quelle est sa capitale ?', null, array['Abou Dabi', 'Pyongyang', 'Achgabat', 'Amman']::text[], 'Pyongyang est la capitale de la Corée du Nord.', 1),
    ('expedition-kp', 2, 'discover', 'Découvrir : Mont Paektu', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Volcan dont le cratère abrite un lac, à la frontière avec la Chine. C''est le point culminant de la péninsule coréenne.', null, 'Mont Paektu fait désormais partie de ton carnet de route.', null),
    ('expedition-kp', 3, 'quiz', 'Défi de connaissances', 'Sur quelle péninsule se trouve la Corée du Nord ?', null, array['La péninsule Malaise', 'La péninsule coréenne', 'La péninsule Arabique', 'La péninsule du Kamtchatka']::text[], 'La Corée du Nord occupe la moitié nord de la péninsule coréenne.', 1),
    ('expedition-ge', 1, 'locate', 'Situer la Géorgie', 'La Géorgie se trouve en Asie (Caucase). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Tbilissi', 'Amman']::text[], 'Tbilissi est la capitale de la Géorgie.', 2),
    ('expedition-ge', 2, 'discover', 'Découvrir : Mtskheta', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancienne capitale du royaume d''Ibérie, au confluent de deux rivières. Ses églises médiévales sont inscrites au patrimoine mondial de l''UNESCO.', null, 'Mtskheta fait désormais partie de ton carnet de route.', null),
    ('expedition-ge', 3, 'quiz', 'Défi de connaissances', 'Dans quel récipient d''argile vinifie-t-on traditionnellement en Géorgie ?', null, array['L''amphore grecque', 'Le fût de chêne', 'Le qvevri', 'La jarre de Canton']::text[], 'Le qvevri est enterré pour la fermentation et la conservation du vin.', 2),
    ('expedition-id', 1, 'locate', 'Situer l''Indonésie', 'L''Indonésie se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Jakarta']::text[], 'Jakarta est la capitale de l''Indonésie.', 3),
    ('expedition-id', 2, 'discover', 'Découvrir : Borobudur', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Temple bouddhiste du IXe siècle en forme de pyramide à degrés. Ses murs sont ornés de plusieurs milliers de bas-reliefs.', null, 'Borobudur fait désormais partie de ton carnet de route.', null),
    ('expedition-id', 3, 'quiz', 'Défi de connaissances', 'Quel temple bouddhiste du IXe siècle se trouve sur l''île de Java ?', null, array['Angkor Vat', 'Wat Arun', 'Shwedagon', 'Borobudur']::text[], 'Borobudur est situé dans le centre de Java.', 3),
    ('expedition-iq', 1, 'locate', 'Situer l''Irak', 'L''Irak se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Bagdad', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Bagdad est la capitale de l''Irak.', 0),
    ('expedition-iq', 2, 'discover', 'Découvrir : Babylone', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ruines de l''une des plus célèbres cités de la Mésopotamie antique, au bord de l''Euphrate. Le site est inscrit au patrimoine mondial de l''UNESCO depuis 2019.', null, 'Babylone fait désormais partie de ton carnet de route.', null),
    ('expedition-iq', 3, 'quiz', 'Défi de connaissances', 'Quels fleuves traversent l''Irak ?', null, array['Le Tigre et l''Euphrate', 'Le Nil et le Jourdain', 'L''Indus et le Gange', 'L''Amou-Daria et le Syr-Daria']::text[], 'Le Tigre et l''Euphrate délimitaient l''antique Mésopotamie.', 0),
    ('expedition-ir', 1, 'locate', 'Situer l''Iran', 'L''Iran se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Téhéran', 'Achgabat', 'Amman']::text[], 'Téhéran est la capitale de l''Iran.', 1),
    ('expedition-ir', 2, 'discover', 'Découvrir : Persépolis', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cité palatiale de l''Empire achéménide, fondée par Darius Ier. Ses escaliers sont décorés de bas-reliefs de délégations apportant des présents.', null, 'Persépolis fait désormais partie de ton carnet de route.', null),
    ('expedition-ir', 3, 'quiz', 'Défi de connaissances', 'Sous quel nom l''Iran était-il longtemps connu en Occident ?', null, array['La Mésopotamie', 'La Perse', 'La Bactriane', 'L''Assyrie']::text[], 'Le nom d''Iran est employé internationalement depuis 1935.', 1),
    ('expedition-il', 1, 'locate', 'Situer Israël', 'Israël se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Jérusalem']::text[], 'Jérusalem est la capitale d''Israël.', 3),
    ('expedition-il', 2, 'discover', 'Découvrir : Massada', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forteresse construite sous Hérode sur un plateau rocheux dominant la mer Morte. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2001.', null, 'Massada fait désormais partie de ton carnet de route.', null),
    ('expedition-il', 3, 'quiz', 'Défi de connaissances', 'Quelle mer la forteresse de Massada domine-t-elle ?', null, array['La mer Rouge', 'La mer de Galilée', 'La Méditerranée', 'La mer Morte']::text[], 'Massada se dresse au-dessus de la rive occidentale de la mer Morte.', 3),
    ('expedition-kz', 1, 'locate', 'Situer le Kazakhstan', 'Le Kazakhstan se trouve en Asie (Asie centrale). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Astana']::text[], 'Astana est la capitale du Kazakhstan.', 3),
    ('expedition-kz', 2, 'discover', 'Découvrir : Cosmodrome de Baïkonour', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Base de lancement spatial installée dans la steppe kazakhe. Youri Gagarine en est parti en 1961 pour le premier vol habité dans l''espace.', null, 'Cosmodrome de Baïkonour fait désormais partie de ton carnet de route.', null),
    ('expedition-kz', 3, 'quiz', 'Défi de connaissances', 'Quel est le plus grand pays enclavé du monde ?', null, array['La Mongolie', 'Le Tchad', 'La Bolivie', 'Le Kazakhstan']::text[], 'Le Kazakhstan n''a aucun accès à l''océan mondial.', 3),
    ('expedition-kg', 1, 'locate', 'Situer le Kirghizistan', 'Le Kirghizistan se trouve en Asie (Asie centrale). Quelle est sa capitale ?', null, array['Bichkek', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Bichkek est la capitale du Kirghizistan.', 0),
    ('expedition-kg', 2, 'discover', 'Découvrir : Lac Issyk-Koul', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Grand lac de montagne situé à plus de 1 600 mètres d''altitude. Malgré l''altitude, il ne gèle pas en hiver, grâce notamment à sa légère salinité.', null, 'Lac Issyk-Koul fait désormais partie de ton carnet de route.', null),
    ('expedition-kg', 3, 'quiz', 'Défi de connaissances', 'Quelle chaîne de montagnes domine le Kirghizistan ?', null, array['Le Tian Shan', 'L''Himalaya', 'Les Andes', 'L''Oural']::text[], 'Le Tian Shan couvre une grande partie du Kirghizistan.', 0),
    ('expedition-kw', 1, 'locate', 'Situer le Koweït', 'Le Koweït se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Koweït', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Koweït est la capitale du Koweït.', 0),
    ('expedition-kw', 2, 'discover', 'Découvrir : Tours du Koweït', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ensemble de trois tours inauguré en 1979 au bord du golfe Persique. Deux tours portent des sphères qui servent notamment de réservoirs d''eau.', null, 'Tours du Koweït fait désormais partie de ton carnet de route.', null),
    ('expedition-kw', 3, 'quiz', 'Défi de connaissances', 'Au fond de quel golfe se trouve le Koweït ?', null, array['Le golfe Persique', 'Le golfe d''Aden', 'Le golfe d''Oman', 'Le golfe du Bengale']::text[], 'Le Koweït est situé au fond du golfe Persique.', 0),
    ('expedition-la', 1, 'locate', 'Situer le Laos', 'Le Laos se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Abou Dabi', 'Vientiane', 'Achgabat', 'Amman']::text[], 'Vientiane est la capitale du Laos.', 1),
    ('expedition-la', 2, 'discover', 'Découvrir : Luang Prabang', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancienne capitale royale aux nombreux temples, au confluent du Mékong et de la Nam Khan. La ville est inscrite au patrimoine mondial de l''UNESCO depuis 1995.', null, 'Luang Prabang fait désormais partie de ton carnet de route.', null),
    ('expedition-la', 3, 'quiz', 'Défi de connaissances', 'Quel fleuve traverse le Laos ?', null, array['Le Yangtsé', 'Le Mékong', 'L''Irrawaddy', 'Le fleuve Rouge']::text[], 'Le Mékong traverse le Laos et forme une partie de sa frontière avec la Thaïlande.', 1),
    ('expedition-lb', 1, 'locate', 'Situer le Liban', 'Le Liban se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Beyrouth', 'Amman']::text[], 'Beyrouth est la capitale du Liban.', 2),
    ('expedition-lb', 2, 'discover', 'Découvrir : Baalbek', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ensemble de temples romains monumentaux dans la vallée de la Bekaa. Le site est inscrit au patrimoine mondial de l''UNESCO depuis 1984.', null, 'Baalbek fait désormais partie de ton carnet de route.', null),
    ('expedition-lb', 3, 'quiz', 'Défi de connaissances', 'Quel arbre figure sur le drapeau du Liban ?', null, array['L''olivier', 'Le palmier', 'Le cèdre', 'Le chêne']::text[], 'Le cèdre du Liban est l''emblème du pays.', 2),
    ('expedition-my', 1, 'locate', 'Situer la Malaisie', 'La Malaisie se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Kuala Lumpur', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Kuala Lumpur est la capitale de la Malaisie.', 0),
    ('expedition-my', 2, 'discover', 'Découvrir : Tours Petronas', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Tours jumelles d''environ 452 mètres reliées par une passerelle. Elles ont été les plus hauts bâtiments du monde de 1998 à 2004.', null, 'Tours Petronas fait désormais partie de ton carnet de route.', null),
    ('expedition-my', 3, 'quiz', 'Défi de connaissances', 'Quelles tours jumelles dominent Kuala Lumpur ?', null, array['Les tours Petronas', 'Les tours Emirates', 'Les tours Etihad', 'Les tours Abraj Al-Bait']::text[], 'Les tours Petronas mesurent environ 452 mètres.', 0),
    ('expedition-mv', 1, 'locate', 'Situer les Maldives', 'Les Maldives se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Malé', 'Achgabat', 'Amman']::text[], 'Malé est la capitale des Maldives.', 1),
    ('expedition-mv', 2, 'discover', 'Découvrir : Atolls des Maldives', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Chapelet d''environ 1 200 îles coralliennes regroupées en atolls. Les récifs qui les entourent abritent une grande diversité de poissons et de coraux.', null, 'Atolls des Maldives fait désormais partie de ton carnet de route.', null),
    ('expedition-mv', 3, 'quiz', 'Défi de connaissances', 'Quelle particularité géographique distingue les Maldives ?', null, array['C''est le pays le plus froid du monde', 'C''est le pays le plus bas du monde', 'C''est le pays le plus montagneux', 'C''est le pays le plus sec du monde']::text[], 'La plupart des îles des Maldives culminent à quelques mètres au-dessus de la mer.', 1),
    ('expedition-mn', 1, 'locate', 'Situer la Mongolie', 'La Mongolie se trouve en Asie (Asie de l''Est). Quelle est sa capitale ?', null, array['Abou Dabi', 'Oulan-Bator', 'Achgabat', 'Amman']::text[], 'Oulan-Bator est la capitale de la Mongolie.', 1),
    ('expedition-mn', 2, 'discover', 'Découvrir : Naadam', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Fête nationale réunissant lutte, course de chevaux et tir à l''arc. Le Naadam est inscrit au patrimoine culturel immatériel de l''UNESCO depuis 2010.', null, 'Naadam fait désormais partie de ton carnet de route.', null),
    ('expedition-mn', 3, 'quiz', 'Défi de connaissances', 'Quelles disciplines sont au cœur du Naadam ?', null, array['Natation, course et escrime', 'Lutte, course de chevaux et tir à l''arc', 'Polo, lutte et ski', 'Boxe, voile et cyclisme']::text[], 'Le Naadam célèbre les « trois jeux virils » : lutte, course de chevaux et tir à l''arc.', 1),
    ('expedition-np', 1, 'locate', 'Situer le Népal', 'Le Népal se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Katmandou', 'Amman']::text[], 'Katmandou est la capitale du Népal.', 2),
    ('expedition-np', 2, 'discover', 'Découvrir : Everest', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Plus haut sommet du monde, à la frontière entre le Népal et la Chine. Sa hauteur a été mesurée en 2020 à 8 848,86 mètres.', null, 'Everest fait désormais partie de ton carnet de route.', null),
    ('expedition-np', 3, 'quiz', 'Défi de connaissances', 'Quelle forme a le drapeau du Népal ?', null, array['Un carré', 'Un cercle', 'Deux triangles superposés', 'Un rectangle allongé']::text[], 'Le drapeau népalais est formé de deux pennons triangulaires superposés.', 2),
    ('expedition-om', 1, 'locate', 'Situer Oman', 'Oman se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Mascate', 'Amman']::text[], 'Mascate est la capitale d''Oman.', 2),
    ('expedition-om', 2, 'discover', 'Découvrir : Aflaj', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Réseaux de canaux d''irrigation qui acheminent l''eau vers les villages et les palmeraies. Cinq de ces systèmes sont inscrits au patrimoine mondial de l''UNESCO depuis 2006.', null, 'Aflaj fait désormais partie de ton carnet de route.', null),
    ('expedition-om', 3, 'quiz', 'Défi de connaissances', 'Quel détroit borde l''exclave omanaise de Musandam ?', null, array['Le détroit de Bab-el-Mandeb', 'Le détroit de Malacca', 'Le détroit d''Ormuz', 'Le Bosphore']::text[], 'Musandam fait face à l''Iran de l''autre côté du détroit d''Ormuz.', 2),
    ('expedition-uz', 1, 'locate', 'Situer l''Ouzbékistan', 'L''Ouzbékistan se trouve en Asie (Asie centrale). Quelle est sa capitale ?', null, array['Abou Dabi', 'Tachkent', 'Achgabat', 'Amman']::text[], 'Tachkent est la capitale de l''Ouzbékistan.', 1),
    ('expedition-uz', 2, 'discover', 'Découvrir : Samarcande', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ville des routes de la soie célèbre pour la place du Registan et ses madrasas. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2001.', null, 'Samarcande fait désormais partie de ton carnet de route.', null),
    ('expedition-uz', 3, 'quiz', 'Défi de connaissances', 'Quelle place célèbre se trouve à Samarcande ?', null, array['La place Rouge', 'Le Registan', 'La place Tian''anmen', 'Jemaa el-Fna']::text[], 'Le Registan est bordé de trois madrasas.', 1),
    ('expedition-pk', 1, 'locate', 'Situer le Pakistan', 'Le Pakistan se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Islamabad']::text[], 'Islamabad est la capitale du Pakistan.', 3),
    ('expedition-pk', 2, 'discover', 'Découvrir : Mohenjo-daro', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ruines d''une grande ville de la civilisation de l''Indus. Ses rues étaient tracées selon un plan régulier et dotées de canalisations.', null, 'Mohenjo-daro fait désormais partie de ton carnet de route.', null),
    ('expedition-pk', 3, 'quiz', 'Défi de connaissances', 'Quelle civilisation a bâti Mohenjo-daro ?', null, array['La civilisation sumérienne', 'L''Empire moghol', 'L''Empire perse', 'La civilisation de l''Indus']::text[], 'Mohenjo-daro est l''une des principales villes de la civilisation de l''Indus.', 3),
    ('expedition-ps', 1, 'locate', 'Situer la Palestine', 'La Palestine se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Ramallah']::text[], 'Ramallah est la capitale de la Palestine.', 3),
    ('expedition-ps', 2, 'discover', 'Découvrir : Église de la Nativité', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Basilique construite sur le lieu traditionnel de la naissance de Jésus. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2012.', null, 'Église de la Nativité fait désormais partie de ton carnet de route.', null),
    ('expedition-ps', 3, 'quiz', 'Défi de connaissances', 'Dans quelle ville se trouve l''église de la Nativité ?', null, array['Nazareth', 'Hébron', 'Jéricho', 'Bethléem']::text[], 'L''église de la Nativité se trouve à Bethléem.', 3),
    ('expedition-ph', 1, 'locate', 'Situer les Philippines', 'Les Philippines se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Manille', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Manille est la capitale des Philippines.', 0),
    ('expedition-ph', 2, 'discover', 'Découvrir : Rizières en terrasses des Cordillères', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Terrasses de rizières sculptées à flanc de montagne par les Ifugao. Elles sont inscrites au patrimoine mondial de l''UNESCO depuis 1995.', null, 'Rizières en terrasses des Cordillères fait désormais partie de ton carnet de route.', null),
    ('expedition-ph', 3, 'quiz', 'Défi de connaissances', 'De quel roi les Philippines tirent-elles leur nom ?', null, array['Philippe II d''Espagne', 'Philippe le Bel', 'Philippe Auguste', 'Philippe V d''Espagne']::text[], 'L''archipel a été nommé en l''honneur de Philippe II d''Espagne.', 0),
    ('expedition-qa', 1, 'locate', 'Situer le Qatar', 'Le Qatar se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Doha', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Doha est la capitale du Qatar.', 0),
    ('expedition-qa', 2, 'discover', 'Découvrir : Al-Zubarah', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancienne ville marchande fortifiée, prospère grâce au commerce des perles. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2013.', null, 'Al-Zubarah fait désormais partie de ton carnet de route.', null),
    ('expedition-qa', 3, 'quiz', 'Défi de connaissances', 'Quel événement le Qatar a-t-il accueilli en 2022 ?', null, array['La Coupe du monde de football', 'Les Jeux olympiques d''été', 'L''Exposition universelle', 'Les Jeux asiatiques']::text[], 'Le Qatar a accueilli la Coupe du monde de football en 2022.', 0),
    ('expedition-sg', 1, 'locate', 'Situer Singapour', 'Singapour se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Singapour', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Singapour est la capitale de Singapour.', 0),
    ('expedition-sg', 2, 'discover', 'Découvrir : Jardin botanique de Singapour', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Jardin tropical fondé au XIXe siècle, qui abrite un célèbre jardin d''orchidées. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2015.', null, 'Jardin botanique de Singapour fait désormais partie de ton carnet de route.', null),
    ('expedition-sg', 3, 'quiz', 'Défi de connaissances', 'Combien de langues officielles compte Singapour ?', null, array['Quatre', 'Une', 'Deux', 'Six']::text[], 'L''anglais, le malais, le mandarin et le tamoul sont langues officielles.', 0),
    ('expedition-lk', 1, 'locate', 'Situer le Sri Lanka', 'Le Sri Lanka se trouve en Asie (Asie du Sud). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Sri Jayawardenapura Kotte']::text[], 'Sri Jayawardenapura Kotte est la capitale du Sri Lanka.', 3),
    ('expedition-lk', 2, 'discover', 'Découvrir : Sigiriya', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forteresse royale du Ve siècle bâtie au sommet d''un rocher. Ses parois conservent des fresques de figures féminines.', null, 'Sigiriya fait désormais partie de ton carnet de route.', null),
    ('expedition-lk', 3, 'quiz', 'Défi de connaissances', 'Quel était l''ancien nom du Sri Lanka ?', null, array['Siam', 'Formose', 'Cathay', 'Ceylan']::text[], 'L''île s''appelait Ceylan jusqu''en 1972.', 3),
    ('expedition-sy', 1, 'locate', 'Situer la Syrie', 'La Syrie se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Damas', 'Amman']::text[], 'Damas est la capitale de la Syrie.', 2),
    ('expedition-sy', 2, 'discover', 'Découvrir : Palmyre', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cité caravanière antique au cœur d''une oasis du désert syrien. Plusieurs de ses monuments ont été détruits en 2015, pendant la guerre.', null, 'Palmyre fait désormais partie de ton carnet de route.', null),
    ('expedition-sy', 3, 'quiz', 'Défi de connaissances', 'Quelle cité caravanière antique se trouve dans le désert syrien ?', null, array['Pétra', 'Persépolis', 'Palmyre', 'Carthage']::text[], 'Palmyre était une étape majeure des caravanes entre l''Orient et la Méditerranée.', 2),
    ('expedition-tj', 1, 'locate', 'Situer le Tadjikistan', 'Le Tadjikistan se trouve en Asie (Asie centrale). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Douchanbé', 'Amman']::text[], 'Douchanbé est la capitale du Tadjikistan.', 2),
    ('expedition-tj', 2, 'discover', 'Découvrir : Pamir', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Haut massif montagneux souvent surnommé « le toit du monde ». Le parc national tadjik des montagnes du Pamir est inscrit au patrimoine mondial de l''UNESCO.', null, 'Pamir fait désormais partie de ton carnet de route.', null),
    ('expedition-tj', 3, 'quiz', 'Défi de connaissances', 'Quel massif est surnommé « le toit du monde » ?', null, array['Les Alpes', 'Les Rocheuses', 'Le Pamir', 'L''Atlas']::text[], 'Le Pamir, au Tadjikistan, est surnommé « le toit du monde ».', 2),
    ('expedition-th', 1, 'locate', 'Situer la Thaïlande', 'La Thaïlande se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Bangkok', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Bangkok est la capitale de la Thaïlande.', 0),
    ('expedition-th', 2, 'discover', 'Découvrir : Ayutthaya', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancienne capitale du royaume de Siam, fondée au XIVe siècle. Ses ruines sont inscrites au patrimoine mondial de l''UNESCO depuis 1991.', null, 'Ayutthaya fait désormais partie de ton carnet de route.', null),
    ('expedition-th', 3, 'quiz', 'Défi de connaissances', 'Quel était l''ancien nom de la Thaïlande ?', null, array['Le Siam', 'La Birmanie', 'L''Annam', 'Le Tonkin']::text[], 'Le pays a pris le nom de Thaïlande en 1939.', 0),
    ('expedition-tl', 1, 'locate', 'Situer le Timor oriental', 'Le Timor oriental se trouve en Asie (Asie du Sud-Est). Quelle est sa capitale ?', null, array['Dili', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Dili est la capitale du Timor oriental.', 0),
    ('expedition-tl', 2, 'discover', 'Découvrir : Tais', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Textile traditionnel tissé à la main, aux motifs propres à chaque région. Le tais est inscrit au patrimoine culturel immatériel de l''UNESCO depuis 2021.', null, 'Tais fait désormais partie de ton carnet de route.', null),
    ('expedition-tl', 3, 'quiz', 'Défi de connaissances', 'En quelle année le Timor oriental est-il devenu indépendant ?', null, array['2002', '1975', '1999', '2011']::text[], 'Le Timor oriental est devenu indépendant le 20 mai 2002.', 0),
    ('expedition-tm', 1, 'locate', 'Situer le Turkménistan', 'Le Turkménistan se trouve en Asie (Asie centrale). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Ankara']::text[], 'Achgabat est la capitale du Turkménistan.', 1),
    ('expedition-tm', 2, 'discover', 'Découvrir : Cratère de Darvaza', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cratère de gaz en feu depuis plusieurs décennies, au milieu du désert. On attribue souvent son origine à un forage soviétique, dont les circonstances restent mal documentées.', null, 'Cratère de Darvaza fait désormais partie de ton carnet de route.', null),
    ('expedition-tm', 3, 'quiz', 'Défi de connaissances', 'Quel désert couvre une grande partie du Turkménistan ?', null, array['Le Gobi', 'Le Karakoum', 'Le Taklamakan', 'Le Kalahari']::text[], 'Le Karakoum s''étend sur la majeure partie du pays.', 1),
    ('expedition-ye', 1, 'locate', 'Situer le Yémen', 'Le Yémen se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Sanaa', 'Abou Dabi', 'Achgabat', 'Amman']::text[], 'Sanaa est la capitale du Yémen.', 0),
    ('expedition-ye', 2, 'discover', 'Découvrir : Shibam', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ville fortifiée aux immeubles de terre crue de plusieurs étages. Elle est souvent surnommée « le Manhattan du désert ».', null, 'Shibam fait désormais partie de ton carnet de route.', null),
    ('expedition-ye', 3, 'quiz', 'Défi de connaissances', 'Quel surnom donne-t-on à la ville de Shibam ?', null, array['Le Manhattan du désert', 'La Venise de l''Orient', 'La perle du Golfe', 'La ville rose']::text[], 'Ses tours de terre crue lui valent le surnom de « Manhattan du désert ».', 0),
    ('expedition-ae', 1, 'locate', 'Situer les Émirats arabes unis', 'Les Émirats arabes unis se trouve en Asie (Asie de l''Ouest). Quelle est sa capitale ?', null, array['Abou Dabi', 'Achgabat', 'Amman', 'Ankara']::text[], 'Abou Dabi est la capitale des Émirats arabes unis.', 0),
    ('expedition-ae', 2, 'discover', 'Découvrir : Burj Khalifa', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Gratte-ciel inauguré en 2010 dans le centre de Dubaï. Haut d''environ 828 mètres, c''est le plus haut bâtiment du monde depuis son inauguration.', null, 'Burj Khalifa fait désormais partie de ton carnet de route.', null),
    ('expedition-ae', 3, 'quiz', 'Défi de connaissances', 'Combien d''émirats forment les Émirats arabes unis ?', null, array['Sept', 'Trois', 'Cinq', 'Neuf']::text[], 'La fédération réunit sept émirats, dont Abou Dabi et Dubaï.', 0),
    ('expedition-dz', 1, 'locate', 'Situer l''Algérie', 'L''Algérie se trouve en Afrique (Afrique du Nord). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Alger', 'Addis-Abeba']::text[], 'Alger est la capitale de l''Algérie.', 2),
    ('expedition-dz', 2, 'discover', 'Découvrir : Casbah d''Alger', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vieille ville d''Alger aux ruelles étroites, bâtie sur une colline dominant la mer. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 1992.', null, 'Casbah d''Alger fait désormais partie de ton carnet de route.', null),
    ('expedition-dz', 3, 'quiz', 'Défi de connaissances', 'Quel surnom donne-t-on souvent à Alger ?', null, array['Alger la Rouge', 'La Ville ocre', 'Alger la Blanche', 'La Perle du désert']::text[], 'Les façades blanches de la ville lui valent le surnom d''« Alger la Blanche ».', 2),
    ('expedition-ao', 1, 'locate', 'Situer l''Angola', 'L''Angola se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Luanda', 'Addis-Abeba']::text[], 'Luanda est la capitale de l''Angola.', 2),
    ('expedition-ao', 2, 'discover', 'Découvrir : Mbanza Kongo', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Site de l''ancienne capitale du royaume du Kongo, dans le nord-ouest de l''Angola. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2017.', null, 'Mbanza Kongo fait désormais partie de ton carnet de route.', null),
    ('expedition-ao', 3, 'quiz', 'Défi de connaissances', 'Quelle est la langue officielle de l''Angola ?', null, array['L''anglais', 'Le français', 'Le portugais', 'L''espagnol']::text[], 'Ancienne colonie portugaise, l''Angola a le portugais pour langue officielle.', 2),
    ('expedition-bw', 1, 'locate', 'Situer le Botswana', 'Le Botswana se trouve en Afrique (Afrique australe). Quelle est sa capitale ?', null, array['Abuja', 'Gaborone', 'Accra', 'Addis-Abeba']::text[], 'Gaborone est la capitale du Botswana.', 1),
    ('expedition-bw', 2, 'discover', 'Découvrir : Delta de l''Okavango', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vaste delta intérieur où le fleuve Okavango se perd dans le Kalahari sans atteindre la mer. Ses crues saisonnières attirent une faune exceptionnelle ; il est inscrit au patrimoine mondial depuis 2014.', null, 'Delta de l''Okavango fait désormais partie de ton carnet de route.', null),
    ('expedition-bw', 3, 'quiz', 'Défi de connaissances', 'Que devient le fleuve Okavango au Botswana ?', null, array['Il se jette dans l''océan Indien', 'Il se perd dans le Kalahari en formant un delta', 'Il rejoint le Nil', 'Il alimente le lac Victoria']::text[], 'L''Okavango forme un delta intérieur et s''évapore dans le Kalahari.', 1),
    ('expedition-bf', 1, 'locate', 'Situer le Burkina Faso', 'Le Burkina Faso se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Ouagadougou', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Ouagadougou est la capitale du Burkina Faso.', 0),
    ('expedition-bf', 2, 'discover', 'Découvrir : Ruines de Loropéni', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vestiges de hauts murs de pierre liés à l''ancien commerce de l''or dans la région. C''est le premier site du pays inscrit au patrimoine mondial, en 2009.', null, 'Ruines de Loropéni fait désormais partie de ton carnet de route.', null),
    ('expedition-bf', 3, 'quiz', 'Défi de connaissances', 'Que signifie « Burkina Faso » ?', null, array['Pays des hommes intègres', 'Terre du fleuve', 'Royaume de l''or', 'Pays du soleil levant']::text[], 'Le nom associe le mooré et le dioula et signifie « pays des hommes intègres ».', 0),
    ('expedition-bi', 1, 'locate', 'Situer le Burundi', 'Le Burundi se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Gitega']::text[], 'Gitega est la capitale du Burundi.', 3),
    ('expedition-bi', 2, 'discover', 'Découvrir : Lac Tanganyika', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Long lac de la vallée du Rift partagé entre quatre pays, dont le Burundi. C''est l''un des lacs les plus profonds et les plus anciens du monde.', null, 'Lac Tanganyika fait désormais partie de ton carnet de route.', null),
    ('expedition-bi', 3, 'quiz', 'Défi de connaissances', 'Quelle ville est la capitale économique du Burundi ?', null, array['Gitega', 'Kigali', 'Goma', 'Bujumbura']::text[], 'Gitega est la capitale politique depuis 2019, Bujumbura demeure le centre économique.', 3),
    ('expedition-bj', 1, 'locate', 'Situer le Bénin', 'Le Bénin se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Porto-Novo', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Porto-Novo est la capitale du Bénin.', 0),
    ('expedition-bj', 2, 'discover', 'Découvrir : Palais royaux d''Abomey', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ensemble de palais en terre des rois du Dahomey, qui régnèrent du XVIIe au XIXe siècle. Leurs bas-reliefs racontent l''histoire et les symboles du royaume.', null, 'Palais royaux d''Abomey fait désormais partie de ton carnet de route.', null),
    ('expedition-bj', 3, 'quiz', 'Défi de connaissances', 'Comment s''appelait le Bénin jusqu''en 1975 ?', null, array['Dahomey', 'Haute-Volta', 'Gold Coast', 'Oubangui-Chari']::text[], 'Le pays a pris le nom de Bénin en 1975 ; il s''appelait auparavant Dahomey.', 0),
    ('expedition-cm', 1, 'locate', 'Situer le Cameroun', 'Le Cameroun se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Yaoundé', 'Addis-Abeba']::text[], 'Yaoundé est la capitale du Cameroun.', 2),
    ('expedition-cm', 2, 'discover', 'Découvrir : Mont Cameroun', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Volcan actif dominant le littoral atlantique du Cameroun. Avec environ 4 000 mètres, c''est le plus haut sommet d''Afrique de l''Ouest et centrale.', null, 'Mont Cameroun fait désormais partie de ton carnet de route.', null),
    ('expedition-cm', 3, 'quiz', 'Défi de connaissances', 'Quelles sont les langues officielles du Cameroun ?', null, array['Le français et l''arabe', 'L''anglais et le portugais', 'Le français et l''anglais', 'Le français et l''espagnol']::text[], 'Le Cameroun est officiellement bilingue : français et anglais.', 2),
    ('expedition-cv', 1, 'locate', 'Situer le Cap-Vert', 'Le Cap-Vert se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Praia']::text[], 'Praia est la capitale du Cap-Vert.', 3),
    ('expedition-cv', 2, 'discover', 'Découvrir : Cidade Velha', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancienne Ribeira Grande, première ville coloniale européenne des tropiques. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2009.', null, 'Cidade Velha fait désormais partie de ton carnet de route.', null),
    ('expedition-cv', 3, 'quiz', 'Défi de connaissances', 'Le Cap-Vert est un archipel de quel océan ?', null, array['L''océan Indien', 'L''océan Pacifique', 'La mer Méditerranée', 'L''océan Atlantique']::text[], 'Le Cap-Vert est situé dans l''Atlantique, à l''ouest du Sénégal.', 3),
    ('expedition-km', 1, 'locate', 'Situer les Comores', 'Les Comores se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Moroni', 'Addis-Abeba']::text[], 'Moroni est la capitale des Comores.', 2),
    ('expedition-km', 2, 'discover', 'Découvrir : Karthala', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Volcan bouclier actif qui occupe une grande partie de l''île de Grande Comore. Ses éruptions successives ont façonné les paysages et les sols de l''île.', null, 'Karthala fait désormais partie de ton carnet de route.', null),
    ('expedition-km', 3, 'quiz', 'Défi de connaissances', 'Entre quels territoires se trouve l''archipel des Comores ?', null, array['Maurice et La Réunion', 'Le Yémen et la Somalie', 'Madagascar et le Mozambique', 'Sri Lanka et les Maldives']::text[], 'Les Comores sont dans le canal du Mozambique, entre Madagascar et le continent.', 2),
    ('expedition-ci', 1, 'locate', 'Situer la Côte d''Ivoire', 'La Côte d''Ivoire se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Yamoussoukro', 'Addis-Abeba']::text[], 'Yamoussoukro est la capitale de la Côte d''Ivoire.', 2),
    ('expedition-ci', 2, 'discover', 'Découvrir : Basilique Notre-Dame-de-la-Paix', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Basilique catholique achevée en 1989, inspirée de Saint-Pierre de Rome. C''est l''une des plus grandes églises du monde.', null, 'Basilique Notre-Dame-de-la-Paix fait désormais partie de ton carnet de route.', null),
    ('expedition-ci', 3, 'quiz', 'Défi de connaissances', 'De quel produit la Côte d''Ivoire est-elle le premier producteur mondial ?', null, array['Le café', 'Le thé', 'Le cacao', 'La vanille']::text[], 'La Côte d''Ivoire est le premier producteur mondial de cacao.', 2),
    ('expedition-dj', 1, 'locate', 'Situer Djibouti', 'Djibouti se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Djibouti', 'Addis-Abeba']::text[], 'Djibouti est la capitale de Djibouti.', 2),
    ('expedition-dj', 2, 'discover', 'Découvrir : Lac Assal', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Lac salé situé dans une dépression, à environ 155 mètres sous le niveau de la mer. C''est le point le plus bas d''Afrique.', null, 'Lac Assal fait désormais partie de ton carnet de route.', null),
    ('expedition-dj', 3, 'quiz', 'Défi de connaissances', 'Quelle particularité le lac Assal possède-t-il ?', null, array['C''est le lac le plus profond d''Afrique', 'Il est gelé toute l''année', 'C''est le point le plus bas d''Afrique', 'C''est la source du Nil']::text[], 'Le lac Assal se trouve à environ 155 mètres sous le niveau de la mer.', 2),
    ('expedition-sz', 1, 'locate', 'Situer l''Eswatini', 'L''Eswatini se trouve en Afrique (Afrique australe). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Mbabane']::text[], 'Mbabane est la capitale de l''Eswatini.', 3),
    ('expedition-sz', 2, 'discover', 'Découvrir : Umhlanga', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cérémonie annuelle des roseaux, au cours de laquelle des jeunes filles offrent des roseaux à la reine mère. C''est l''un des grands événements culturels du royaume.', null, 'Umhlanga fait désormais partie de ton carnet de route.', null),
    ('expedition-sz', 3, 'quiz', 'Défi de connaissances', 'Quel était l''ancien nom de l''Eswatini ?', null, array['Lesotho', 'Zoulouland', 'Bechuanaland', 'Swaziland']::text[], 'Le pays a pris le nom d''Eswatini en 2018.', 3),
    ('expedition-ga', 1, 'locate', 'Situer le Gabon', 'Le Gabon se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Libreville', 'Addis-Abeba']::text[], 'Libreville est la capitale du Gabon.', 2),
    ('expedition-ga', 2, 'discover', 'Découvrir : Parc national de la Lopé', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Mosaïque de forêts et de savanes au cœur du Gabon. Il est inscrit au patrimoine mondial pour sa biodiversité et ses vestiges archéologiques.', null, 'Parc national de la Lopé fait désormais partie de ton carnet de route.', null),
    ('expedition-ga', 3, 'quiz', 'Défi de connaissances', 'Que rappelle le nom de Libreville ?', null, array['Une victoire militaire', 'Le nom d''un explorateur', 'La fondation de la ville par des esclaves libérés', 'Une ancienne mine d''or']::text[], 'Libreville a été fondée en 1849 par des esclaves libérés.', 2),
    ('expedition-gm', 1, 'locate', 'Situer la Gambie', 'La Gambie se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Banjul', 'Addis-Abeba']::text[], 'Banjul est la capitale de la Gambie.', 2),
    ('expedition-gm', 2, 'discover', 'Découvrir : Île Kunta Kinteh', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Petite île du fleuve Gambie marquée par les vestiges d''un fort colonial. Elle est inscrite au patrimoine mondial comme lieu de mémoire de la traite des esclaves.', null, 'Île Kunta Kinteh fait désormais partie de ton carnet de route.', null),
    ('expedition-gm', 3, 'quiz', 'Défi de connaissances', 'Quel pays entoure presque entièrement la Gambie ?', null, array['La Guinée', 'Le Mali', 'Le Sénégal', 'La Mauritanie']::text[], 'La Gambie est enclavée dans le Sénégal, à l''exception de sa façade atlantique.', 2),
    ('expedition-gh', 1, 'locate', 'Situer le Ghana', 'Le Ghana se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Alger']::text[], 'Accra est la capitale du Ghana.', 1),
    ('expedition-gh', 2, 'discover', 'Découvrir : Château de Cape Coast', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forteresse côtière utilisée pendant la traite atlantique des esclaves. Il fait partie des forts et châteaux du Ghana inscrits au patrimoine mondial en 1979.', null, 'Château de Cape Coast fait désormais partie de ton carnet de route.', null),
    ('expedition-gh', 3, 'quiz', 'Défi de connaissances', 'Quel était le nom colonial du Ghana ?', null, array['La Haute-Volta', 'La Côte-de-l''Or', 'Le Dahomey', 'La Rhodésie']::text[], 'Sous domination britannique, le territoire s''appelait la Gold Coast, ou Côte-de-l''Or.', 1),
    ('expedition-gn', 1, 'locate', 'Situer la Guinée', 'La Guinée se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Conakry']::text[], 'Conakry est la capitale de la Guinée.', 3),
    ('expedition-gn', 2, 'discover', 'Découvrir : Mont Nimba', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Montagne couverte de forêts, aux confins de la Guinée, de la Côte d''Ivoire et du Liberia. Sa réserve naturelle intégrale est inscrite au patrimoine mondial.', null, 'Mont Nimba fait désormais partie de ton carnet de route.', null),
    ('expedition-gn', 3, 'quiz', 'Défi de connaissances', 'Quel surnom donne-t-on à la Guinée ?', null, array['Le pays de l''or', 'La perle du Sahel', 'Le grenier de l''Afrique', 'Le château d''eau de l''Afrique de l''Ouest']::text[], 'Plusieurs grands fleuves d''Afrique de l''Ouest prennent leur source en Guinée.', 3),
    ('expedition-gq', 1, 'locate', 'Situer la Guinée équatoriale', 'La Guinée équatoriale se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Malabo', 'Addis-Abeba']::text[], 'Malabo est la capitale de la Guinée équatoriale.', 2),
    ('expedition-gq', 2, 'discover', 'Découvrir : Île de Bioko', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Île volcanique couverte de forêts, au large du Cameroun. Ses plages accueillent la ponte de plusieurs espèces de tortues marines.', null, 'Île de Bioko fait désormais partie de ton carnet de route.', null),
    ('expedition-gq', 3, 'quiz', 'Défi de connaissances', 'Quelle langue officielle distingue la Guinée équatoriale en Afrique ?', null, array['Le portugais', 'L''italien', 'L''espagnol', 'Le néerlandais']::text[], 'C''est le seul pays africain ayant l''espagnol pour langue officielle.', 2),
    ('expedition-gw', 1, 'locate', 'Situer la Guinée-Bissau', 'La Guinée-Bissau se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Bissau', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Bissau est la capitale de la Guinée-Bissau.', 0),
    ('expedition-gw', 2, 'discover', 'Découvrir : Archipel des Bijagos', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ensemble de dizaines d''îles aux mangroves et aux plages préservées. Il est reconnu réserve de biosphère par l''UNESCO.', null, 'Archipel des Bijagos fait désormais partie de ton carnet de route.', null),
    ('expedition-gw', 3, 'quiz', 'Défi de connaissances', 'Quel archipel appartient à la Guinée-Bissau ?', null, array['Les Bijagos', 'Les Comores', 'Les Canaries', 'Le Cap-Vert']::text[], 'L''archipel des Bijagos fait face aux côtes de la Guinée-Bissau.', 0),
    ('expedition-ke', 1, 'locate', 'Situer le Kenya', 'Le Kenya se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Nairobi', 'Addis-Abeba']::text[], 'Nairobi est la capitale du Kenya.', 2),
    ('expedition-ke', 2, 'discover', 'Découvrir : Réserve nationale du Masai Mara', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Savane prolongeant le Serengeti tanzanien. Elle est célèbre pour la grande migration des gnous et des zèbres.', null, 'Réserve nationale du Masai Mara fait désormais partie de ton carnet de route.', null),
    ('expedition-ke', 3, 'quiz', 'Défi de connaissances', 'Quel phénomène rend le Masai Mara célèbre ?', null, array['Les aurores boréales', 'Les geysers', 'La grande migration des gnous', 'La migration des manchots']::text[], 'Chaque année, gnous et zèbres traversent le Masai Mara.', 2),
    ('expedition-ls', 1, 'locate', 'Situer le Lesotho', 'Le Lesotho se trouve en Afrique (Afrique australe). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Maseru']::text[], 'Maseru est la capitale du Lesotho.', 3),
    ('expedition-ls', 2, 'discover', 'Découvrir : Chapeau basotho', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Chapeau de paille conique, emblème national du Lesotho. Sa silhouette figure sur le drapeau du pays.', null, 'Chapeau basotho fait désormais partie de ton carnet de route.', null),
    ('expedition-ls', 3, 'quiz', 'Défi de connaissances', 'Quel pays entoure entièrement le Lesotho ?', null, array['Le Botswana', 'Le Mozambique', 'La Namibie', 'L''Afrique du Sud']::text[], 'Le Lesotho est enclavé dans l''Afrique du Sud.', 3),
    ('expedition-lr', 1, 'locate', 'Situer le Liberia', 'Le Liberia se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Monrovia', 'Addis-Abeba']::text[], 'Monrovia est la capitale du Liberia.', 2),
    ('expedition-lr', 2, 'discover', 'Découvrir : Parc national de Sapo', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Le plus grand parc national du Liberia, couvert de forêt tropicale. Il abrite notamment l''hippopotame pygmée.', null, 'Parc national de Sapo fait désormais partie de ton carnet de route.', null),
    ('expedition-lr', 3, 'quiz', 'Défi de connaissances', 'À qui la ville de Monrovia doit-elle son nom ?', null, array['À un explorateur portugais', 'À un roi local', 'Au président américain James Monroe', 'À un missionnaire français']::text[], 'Monrovia porte le nom de James Monroe, président des États-Unis.', 2),
    ('expedition-ly', 1, 'locate', 'Situer la Libye', 'La Libye se trouve en Afrique (Afrique du Nord). Quelle est sa capitale ?', null, array['Abuja', 'Tripoli', 'Accra', 'Addis-Abeba']::text[], 'Tripoli est la capitale de la Libye.', 1),
    ('expedition-ly', 2, 'discover', 'Découvrir : Leptis Magna', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vestiges d''une grande cité romaine au bord de la Méditerranée. Elle fut la ville natale de l''empereur Septime Sévère, qui l''embellit.', null, 'Leptis Magna fait désormais partie de ton carnet de route.', null),
    ('expedition-ly', 3, 'quiz', 'Défi de connaissances', 'Quel empereur romain est né à Leptis Magna ?', null, array['Auguste', 'Septime Sévère', 'Néron', 'Hadrien']::text[], 'Septime Sévère, né à Leptis Magna, a fait de sa ville natale une cité monumentale.', 1),
    ('expedition-mg', 1, 'locate', 'Situer Madagascar', 'Madagascar se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Antananarivo', 'Addis-Abeba']::text[], 'Antananarivo est la capitale de Madagascar.', 2),
    ('expedition-mg', 2, 'discover', 'Découvrir : Allée des Baobabs', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Alignement de grands baobabs le long d''une piste, près de Morondava. Ces arbres peuvent vivre plusieurs siècles.', null, 'Allée des Baobabs fait désormais partie de ton carnet de route.', null),
    ('expedition-mg', 3, 'quiz', 'Défi de connaissances', 'Quels animaux sont emblématiques de Madagascar ?', null, array['Les kangourous', 'Les pandas', 'Les lémuriens', 'Les bisons']::text[], 'Les lémuriens ne vivent à l''état sauvage qu''à Madagascar.', 2),
    ('expedition-mw', 1, 'locate', 'Situer le Malawi', 'Le Malawi se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Lilongwe', 'Addis-Abeba']::text[], 'Lilongwe est la capitale du Malawi.', 2),
    ('expedition-mw', 2, 'discover', 'Découvrir : Lac Malawi', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Grand lac de la vallée du Rift partagé avec le Mozambique et la Tanzanie. Il abrite des centaines d''espèces de poissons cichlidés, pour la plupart endémiques.', null, 'Lac Malawi fait désormais partie de ton carnet de route.', null),
    ('expedition-mw', 3, 'quiz', 'Défi de connaissances', 'Quels poissons rendent le lac Malawi célèbre ?', null, array['Les saumons', 'Les requins', 'Les cichlidés', 'Les esturgeons']::text[], 'Le lac Malawi abrite des centaines d''espèces de cichlidés.', 2),
    ('expedition-ml', 1, 'locate', 'Situer le Mali', 'Le Mali se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Bamako']::text[], 'Bamako est la capitale du Mali.', 3),
    ('expedition-ml', 2, 'discover', 'Découvrir : Grande Mosquée de Djenné', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Mosquée en terre crue, considérée comme le plus grand édifice en banco du monde. Son enduit est renouvelé chaque année lors d''une grande fête collective.', null, 'Grande Mosquée de Djenné fait désormais partie de ton carnet de route.', null),
    ('expedition-ml', 3, 'quiz', 'Défi de connaissances', 'En quel matériau la Grande Mosquée de Djenné est-elle construite ?', null, array['En pierre de taille', 'En bois', 'En marbre', 'En terre crue']::text[], 'La mosquée est bâtie en banco, une terre crue renouvelée chaque année.', 3),
    ('expedition-mu', 1, 'locate', 'Situer Maurice', 'Maurice se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Port-Louis', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Port-Louis est la capitale de Maurice.', 0),
    ('expedition-mu', 2, 'discover', 'Découvrir : Aapravasi Ghat', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancien dépôt d''immigration où arrivaient les travailleurs engagés, venus surtout d''Inde. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2006.', null, 'Aapravasi Ghat fait désormais partie de ton carnet de route.', null),
    ('expedition-mu', 3, 'quiz', 'Défi de connaissances', 'Quel oiseau disparu est le symbole de Maurice ?', null, array['Le dodo', 'Le moa', 'Le grand pingouin', 'Le pigeon migrateur']::text[], 'Le dodo vivait à Maurice avant de disparaître au XVIIe siècle.', 0),
    ('expedition-mr', 1, 'locate', 'Situer la Mauritanie', 'La Mauritanie se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Nouakchott', 'Accra', 'Addis-Abeba']::text[], 'Nouakchott est la capitale de la Mauritanie.', 1),
    ('expedition-mr', 2, 'discover', 'Découvrir : Structure de Richat', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Immense formation circulaire de roches dans le Sahara, d''environ 40 kilomètres de diamètre. Longtemps prise pour un cratère d''impact, elle résulte de l''érosion d''un dôme géologique.', null, 'Structure de Richat fait désormais partie de ton carnet de route.', null),
    ('expedition-mr', 3, 'quiz', 'Défi de connaissances', 'Comment s''est formée la structure de Richat ?', null, array['Par l''impact d''une météorite', 'Par l''érosion d''un dôme géologique', 'Par une éruption volcanique', 'Par l''action humaine']::text[], 'La structure de Richat est un dôme géologique dégagé par l''érosion.', 1),
    ('expedition-mz', 1, 'locate', 'Situer le Mozambique', 'Le Mozambique se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Maputo', 'Accra', 'Addis-Abeba']::text[], 'Maputo est la capitale du Mozambique.', 1),
    ('expedition-mz', 2, 'discover', 'Découvrir : Île de Mozambique', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Petite île fortifiée qui fut un comptoir portugais sur la route des Indes. Elle a donné son nom au pays et est inscrite au patrimoine mondial.', null, 'Île de Mozambique fait désormais partie de ton carnet de route.', null),
    ('expedition-mz', 3, 'quiz', 'Défi de connaissances', 'Quel était l''ancien nom de Maputo ?', null, array['Salisbury', 'Lourenço Marques', 'Léopoldville', 'Fort-Lamy']::text[], 'La capitale a pris le nom de Maputo en 1976.', 1),
    ('expedition-na', 1, 'locate', 'Situer la Namibie', 'La Namibie se trouve en Afrique (Afrique australe). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Windhoek']::text[], 'Windhoek est la capitale de la Namibie.', 3),
    ('expedition-na', 2, 'discover', 'Découvrir : Dunes de Sossusvlei', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Dunes de sable orangé parmi les plus hautes du monde, au cœur du Namib. Le désert du Namib est considéré comme l''un des plus anciens du monde.', null, 'Dunes de Sossusvlei fait désormais partie de ton carnet de route.', null),
    ('expedition-na', 3, 'quiz', 'Défi de connaissances', 'Quel désert longe la côte namibienne ?', null, array['Le Kalahari', 'Le Sahara', 'Le Gobi', 'Le Namib']::text[], 'Le Namib s''étend le long de la côte atlantique de la Namibie.', 3),
    ('expedition-ne', 1, 'locate', 'Situer le Niger', 'Le Niger se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Niamey']::text[], 'Niamey est la capitale du Niger.', 3),
    ('expedition-ne', 2, 'discover', 'Découvrir : Centre historique d''Agadez', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vieille ville caravanière aux portes du Sahara. Son minaret en terre crue, haut d''environ 27 mètres, est le plus haut de ce type au monde.', null, 'Centre historique d''Agadez fait désormais partie de ton carnet de route.', null),
    ('expedition-ne', 3, 'quiz', 'Défi de connaissances', 'À quoi le Niger doit-il son nom ?', null, array['À une montagne', 'À un désert', 'À un ancien roi', 'À un fleuve']::text[], 'Le pays porte le nom du fleuve Niger.', 3),
    ('expedition-ng', 1, 'locate', 'Situer le Nigeria', 'Le Nigeria se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Accra', 'Abuja', 'Addis-Abeba', 'Alger']::text[], 'Abuja est la capitale du Nigeria.', 1),
    ('expedition-ng', 2, 'discover', 'Découvrir : Bosquet sacré d''Osun-Osogbo', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forêt sacrée au bord de la rivière Osun, consacrée à la divinité yoruba de la fertilité. Ornée de sculptures, elle est inscrite au patrimoine mondial depuis 2005.', null, 'Bosquet sacré d''Osun-Osogbo fait désormais partie de ton carnet de route.', null),
    ('expedition-ng', 3, 'quiz', 'Défi de connaissances', 'Quelle ville était la capitale du Nigeria avant Abuja ?', null, array['Ibadan', 'Lagos', 'Kano', 'Port Harcourt']::text[], 'Abuja a remplacé Lagos comme capitale en 1991.', 1),
    ('expedition-ug', 1, 'locate', 'Situer l''Ouganda', 'L''Ouganda se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Kampala', 'Addis-Abeba']::text[], 'Kampala est la capitale de l''Ouganda.', 2),
    ('expedition-ug', 2, 'discover', 'Découvrir : Forêt impénétrable de Bwindi', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forêt tropicale de montagne très dense. Elle abrite près de la moitié des gorilles de montagne du monde.', null, 'Forêt impénétrable de Bwindi fait désormais partie de ton carnet de route.', null),
    ('expedition-ug', 3, 'quiz', 'Défi de connaissances', 'Sur les rives de quel grand lac se trouve l''Ouganda ?', null, array['Le lac Tchad', 'Le lac Baïkal', 'Le lac Victoria', 'Le lac Titicaca']::text[], 'L''Ouganda partage le lac Victoria avec le Kenya et la Tanzanie.', 2),
    ('expedition-rw', 1, 'locate', 'Situer le Rwanda', 'Le Rwanda se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Kigali', 'Accra', 'Addis-Abeba']::text[], 'Kigali est la capitale du Rwanda.', 1),
    ('expedition-rw', 2, 'discover', 'Découvrir : Parc national des Volcans', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Parc de la chaîne des Virunga, à la frontière de la RDC et de l''Ouganda. Il protège une partie des derniers gorilles de montagne.', null, 'Parc national des Volcans fait désormais partie de ton carnet de route.', null),
    ('expedition-rw', 3, 'quiz', 'Défi de connaissances', 'Quel surnom donne-t-on au Rwanda ?', null, array['Le pays des mille lacs', 'Le pays des mille collines', 'Le toit de l''Afrique', 'La perle du Nil']::text[], 'Le relief très vallonné du Rwanda lui vaut ce surnom.', 1),
    ('expedition-cf', 1, 'locate', 'Situer la République centrafricaine', 'La République centrafricaine se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Bangui']::text[], 'Bangui est la capitale de la République centrafricaine.', 3),
    ('expedition-cf', 2, 'discover', 'Découvrir : Parc national du Manovo-Gounda St Floris', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vaste parc de savanes et de plaines inondables du nord du pays. Inscrit au patrimoine mondial en 1988, il figure sur la liste du patrimoine en péril.', null, 'Parc national du Manovo-Gounda St Floris fait désormais partie de ton carnet de route.', null),
    ('expedition-cf', 3, 'quiz', 'Défi de connaissances', 'Quelle langue est officielle en Centrafrique avec le français ?', null, array['Le lingala', 'Le swahili', 'Le haoussa', 'Le sango']::text[], 'Le sango, parlé dans tout le pays, est langue officielle avec le français.', 3),
    ('expedition-cg', 1, 'locate', 'Situer la République du Congo', 'La République du Congo se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Brazzaville', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Brazzaville est la capitale de la République du Congo.', 0),
    ('expedition-cg', 2, 'discover', 'Découvrir : Parc national d''Odzala-Kokoua', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Grand parc de forêt tropicale et de savanes du bassin du Congo. Il abrite des gorilles des plaines de l''Ouest et des éléphants de forêt.', null, 'Parc national d''Odzala-Kokoua fait désormais partie de ton carnet de route.', null),
    ('expedition-cg', 3, 'quiz', 'Défi de connaissances', 'Quelle capitale fait face à Brazzaville de l''autre côté du fleuve Congo ?', null, array['Kinshasa', 'Libreville', 'Bangui', 'Luanda']::text[], 'Kinshasa, capitale de la RDC, se trouve sur l''autre rive du fleuve.', 0),
    ('expedition-cd', 1, 'locate', 'Situer la République démocratique du Congo', 'La République démocratique du Congo se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'Kinshasa', 'Accra', 'Addis-Abeba']::text[], 'Kinshasa est la capitale de la République démocratique du Congo.', 1),
    ('expedition-cd', 2, 'discover', 'Découvrir : Parc national des Virunga', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Parc de volcans, de forêts et de savanes à la frontière du Rwanda et de l''Ouganda. Créé en 1925, c''est le plus ancien parc national d''Afrique ; il abrite des gorilles de montagne.', null, 'Parc national des Virunga fait désormais partie de ton carnet de route.', null),
    ('expedition-cd', 3, 'quiz', 'Défi de connaissances', 'Quel animal emblématique vit dans le parc des Virunga ?', null, array['Le panda roux', 'Le gorille de montagne', 'Le lémurien', 'Le koala']::text[], 'Le parc protège une partie des derniers gorilles de montagne.', 1),
    ('expedition-sc', 1, 'locate', 'Situer les Seychelles', 'Les Seychelles se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Victoria', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Victoria est la capitale des Seychelles.', 0),
    ('expedition-sc', 2, 'discover', 'Découvrir : Vallée de Mai', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forêt de palmiers préservée de l''île de Praslin. Elle abrite le coco de mer, dont la graine est la plus grosse du règne végétal.', null, 'Vallée de Mai fait désormais partie de ton carnet de route.', null),
    ('expedition-sc', 3, 'quiz', 'Défi de connaissances', 'Quel record détient la graine du coco de mer ?', null, array['La plus grosse graine du règne végétal', 'La plus petite graine', 'La plus vieille graine', 'La seule graine bleue']::text[], 'Le coco de mer produit la plus grosse graine du monde végétal.', 0),
    ('expedition-sl', 1, 'locate', 'Situer la Sierra Leone', 'La Sierra Leone se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Freetown', 'Accra', 'Addis-Abeba']::text[], 'Freetown est la capitale de la Sierra Leone.', 1),
    ('expedition-sl', 2, 'discover', 'Découvrir : Île de Tiwai', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Île forestière protégée sur la rivière Moa. Elle abrite une grande diversité de primates.', null, 'Île de Tiwai fait désormais partie de ton carnet de route.', null),
    ('expedition-sl', 3, 'quiz', 'Défi de connaissances', 'Pour accueillir qui Freetown a-t-elle été fondée ?', null, array['Des marchands arabes', 'Des esclaves libérés', 'Des colons français', 'Des missionnaires danois']::text[], 'Freetown a été fondée à la fin du XVIIIe siècle pour accueillir des esclaves libérés.', 1),
    ('expedition-so', 1, 'locate', 'Situer la Somalie', 'La Somalie se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Mogadiscio', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Mogadiscio est la capitale de la Somalie.', 0),
    ('expedition-so', 2, 'discover', 'Découvrir : Laas Geel', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ensemble d''abris sous roche ornés de peintures rupestres. Ses peintures représentent notamment des bovins et des figures humaines.', null, 'Laas Geel fait désormais partie de ton carnet de route.', null),
    ('expedition-so', 3, 'quiz', 'Défi de connaissances', 'Quel record détient la Somalie en Afrique ?', null, array['Le plus long littoral d''Afrique continentale', 'Le plus haut sommet', 'Le plus grand lac', 'Le plus long fleuve']::text[], 'La Somalie borde le golfe d''Aden et l''océan Indien sur une très grande longueur.', 0),
    ('expedition-sd', 1, 'locate', 'Situer le Soudan', 'Le Soudan se trouve en Afrique (Afrique du Nord). Quelle est sa capitale ?', null, array['Abuja', 'Khartoum', 'Accra', 'Addis-Abeba']::text[], 'Khartoum est la capitale du Soudan.', 1),
    ('expedition-sd', 2, 'discover', 'Découvrir : Pyramides de Méroé', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Nécropole royale de pyramides aux pentes abruptes, au nord de Khartoum. Elles témoignent du royaume de Koush, dont Méroé fut la capitale.', null, 'Pyramides de Méroé fait désormais partie de ton carnet de route.', null),
    ('expedition-sd', 3, 'quiz', 'Défi de connaissances', 'Quels cours d''eau se rejoignent à Khartoum ?', null, array['Le Tigre et l''Euphrate', 'Le Nil Blanc et le Nil Bleu', 'Le Congo et l''Oubangui', 'Le Niger et la Bénoué']::text[], 'Le Nil Blanc et le Nil Bleu se rejoignent à Khartoum.', 1),
    ('expedition-ss', 1, 'locate', 'Situer le Soudan du Sud', 'Le Soudan du Sud se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Djouba', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'Djouba est la capitale du Soudan du Sud.', 0),
    ('expedition-ss', 2, 'discover', 'Découvrir : Le Sudd', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Immense zone de marais formée par le Nil Blanc. C''est l''une des plus vastes zones humides du monde.', null, 'Le Sudd fait désormais partie de ton carnet de route.', null),
    ('expedition-ss', 3, 'quiz', 'Défi de connaissances', 'En quelle année le Soudan du Sud est-il devenu indépendant ?', null, array['2011', '1956', '1993', '2019']::text[], 'Le Soudan du Sud est devenu indépendant en 2011.', 0),
    ('expedition-st', 1, 'locate', 'Situer São Tomé-et-Principe', 'São Tomé-et-Principe se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['Abuja', 'São Tomé', 'Accra', 'Addis-Abeba']::text[], 'São Tomé est la capitale de São Tomé-et-Principe.', 1),
    ('expedition-st', 2, 'discover', 'Découvrir : Pico Cão Grande', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Pic volcanique en forme d''aiguille dominant la forêt tropicale. Il s''élève à plus de 300 mètres au-dessus du terrain environnant.', null, 'Pico Cão Grande fait désormais partie de ton carnet de route.', null),
    ('expedition-st', 3, 'quiz', 'Défi de connaissances', 'Quelle ligne imaginaire traverse São Tomé-et-Principe ?', null, array['Le tropique du Cancer', 'L''équateur', 'Le méridien de Greenwich', 'Le cercle polaire']::text[], 'L''équateur passe par l''îlot das Rolas, au sud de São Tomé.', 1),
    ('expedition-td', 1, 'locate', 'Situer le Tchad', 'Le Tchad se trouve en Afrique (Afrique centrale). Quelle est sa capitale ?', null, array['N''Djaména', 'Abuja', 'Accra', 'Addis-Abeba']::text[], 'N''Djaména est la capitale du Tchad.', 0),
    ('expedition-td', 2, 'discover', 'Découvrir : Massif de l''Ennedi', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Plateau de grès sculpté par le vent et l''eau en arches, piliers et canyons. Il abrite de nombreuses peintures rupestres et est inscrit au patrimoine mondial depuis 2016.', null, 'Massif de l''Ennedi fait désormais partie de ton carnet de route.', null),
    ('expedition-td', 3, 'quiz', 'Défi de connaissances', 'D''où le Tchad tire-t-il son nom ?', null, array['D''un lac', 'D''un fleuve', 'D''une montagne', 'D''un ancien roi']::text[], 'Le pays porte le nom du lac Tchad.', 0),
    ('expedition-tg', 1, 'locate', 'Situer le Togo', 'Le Togo se trouve en Afrique (Afrique de l''Ouest). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Lomé']::text[], 'Lomé est la capitale du Togo.', 3),
    ('expedition-tg', 2, 'discover', 'Découvrir : Koutammakou', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Paysage des Batammariba, connus pour leurs maisons-tours en terre appelées takientas. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2004.', null, 'Koutammakou fait désormais partie de ton carnet de route.', null),
    ('expedition-tg', 3, 'quiz', 'Défi de connaissances', 'Comment appelle-t-on les maisons-tours en terre du Koutammakou ?', null, array['Les ksour', 'Les rondavels', 'Les igloos', 'Les takientas']::text[], 'Les Batammariba construisent des maisons-tours appelées takientas.', 3),
    ('expedition-tn', 1, 'locate', 'Situer la Tunisie', 'La Tunisie se trouve en Afrique (Afrique du Nord). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Tunis', 'Addis-Abeba']::text[], 'Tunis est la capitale de la Tunisie.', 2),
    ('expedition-tn', 2, 'discover', 'Découvrir : Site de Carthage', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vestiges de la cité fondée par les Phéniciens, rivale de Rome dans l''Antiquité. Détruite par Rome en 146 av. J.-C., elle fut reconstruite et devint une grande ville romaine.', null, 'Site de Carthage fait désormais partie de ton carnet de route.', null),
    ('expedition-tn', 3, 'quiz', 'Défi de connaissances', 'Quel peuple a fondé Carthage ?', null, array['Les Grecs', 'Les Romains', 'Les Phéniciens', 'Les Égyptiens']::text[], 'Carthage a été fondée par des colons phéniciens venus de Tyr.', 2),
    ('expedition-zm', 1, 'locate', 'Situer la Zambie', 'La Zambie se trouve en Afrique (Afrique australe). Quelle est sa capitale ?', null, array['Abuja', 'Accra', 'Addis-Abeba', 'Lusaka']::text[], 'Lusaka est la capitale de la Zambie.', 3),
    ('expedition-zm', 2, 'discover', 'Découvrir : Chutes Victoria', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Chutes du Zambèze à la frontière de la Zambie et du Zimbabwe. Leur nom local, Mosi-oa-Tunya, signifie « la fumée qui gronde ».', null, 'Chutes Victoria fait désormais partie de ton carnet de route.', null),
    ('expedition-zm', 3, 'quiz', 'Défi de connaissances', 'Que signifie Mosi-oa-Tunya, nom local des chutes Victoria ?', null, array['L''eau qui chante', 'Le grand serpent', 'La porte du ciel', 'La fumée qui gronde']::text[], 'Les embruns visibles de loin ont inspiré ce nom.', 3),
    ('expedition-zw', 1, 'locate', 'Situer le Zimbabwe', 'Le Zimbabwe se trouve en Afrique (Afrique australe). Quelle est sa capitale ?', null, array['Abuja', 'Harare', 'Accra', 'Addis-Abeba']::text[], 'Harare est la capitale du Zimbabwe.', 1),
    ('expedition-zw', 2, 'discover', 'Découvrir : Grand Zimbabwe', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ruines d''une cité médiévale aux murs de pierres sèches assemblées sans mortier. Elle fut la capitale d''un royaume shona entre le XIe et le XVe siècle.', null, 'Grand Zimbabwe fait désormais partie de ton carnet de route.', null),
    ('expedition-zw', 3, 'quiz', 'Défi de connaissances', 'Comment les murs du Grand Zimbabwe ont-ils été construits ?', null, array['En briques cuites', 'En pierres sèches sans mortier', 'En béton', 'En bois']::text[], 'Les murs sont faits de blocs de granite empilés sans mortier.', 1),
    ('expedition-er', 1, 'locate', 'Situer l''Érythrée', 'L''Érythrée se trouve en Afrique (Afrique de l''Est). Quelle est sa capitale ?', null, array['Abuja', 'Asmara', 'Accra', 'Addis-Abeba']::text[], 'Asmara est la capitale de l''Érythrée.', 1),
    ('expedition-er', 2, 'discover', 'Découvrir : Asmara, ville moderniste', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Centre-ville bâti en grande partie à l''époque coloniale italienne, de style moderniste et Art déco. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2017.', null, 'Asmara, ville moderniste fait désormais partie de ton carnet de route.', null),
    ('expedition-er', 3, 'quiz', 'Défi de connaissances', 'En quelle année l''Érythrée est-elle devenue indépendante ?', null, array['1960', '1993', '1975', '2011']::text[], 'L''Érythrée a obtenu son indépendance de l''Éthiopie en 1993.', 1),
    ('expedition-ag', 1, 'locate', 'Situer Antigua-et-Barbuda', 'Antigua-et-Barbuda se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Saint John''s', 'Bridgetown']::text[], 'Saint John''s est la capitale d''Antigua-et-Barbuda.', 2),
    ('expedition-ag', 2, 'discover', 'Découvrir : Chantier naval de Nelson', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancien chantier naval britannique du XVIIIe siècle, abrité dans une baie d''Antigua. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2016.', null, 'Chantier naval de Nelson fait désormais partie de ton carnet de route.', null),
    ('expedition-ag', 3, 'quiz', 'Défi de connaissances', 'Quel ancien chantier naval britannique se visite à Antigua ?', null, array['L''arsenal de Toulon', 'Le chantier de Portsmouth', 'Le chantier naval de Nelson', 'Le port de Brest']::text[], 'Le chantier naval de Nelson, à English Harbour, date du XVIIIe siècle.', 2),
    ('expedition-bs', 1, 'locate', 'Situer les Bahamas', 'Les Bahamas se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Nassau', 'Belmopan', 'Bridgetown']::text[], 'Nassau est la capitale des Bahamas.', 1),
    ('expedition-bs', 2, 'discover', 'Découvrir : Junkanoo', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Défilé de rue nocturne en musique et en costumes colorés, organisé autour de Noël et du Nouvel An. Les costumes sont traditionnellement fabriqués en carton et en papier crépon.', null, 'Junkanoo fait désormais partie de ton carnet de route.', null),
    ('expedition-bs', 3, 'quiz', 'Défi de connaissances', 'Quel défilé costumé anime les rues des Bahamas à la fin de l''année ?', null, array['Le carnaval de Rio', 'Le Junkanoo', 'Le Mardi gras', 'Le Crop Over']::text[], 'Le Junkanoo se déroule autour de Noël et du Nouvel An.', 1),
    ('expedition-bb', 1, 'locate', 'Situer la Barbade', 'La Barbade se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Bridgetown', 'Basseterre', 'Belmopan', 'Castries']::text[], 'Bridgetown est la capitale de la Barbade.', 0),
    ('expedition-bb', 2, 'discover', 'Découvrir : Crop Over', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Festival estival qui célébrait à l''origine la fin de la récolte de la canne à sucre. Il culmine avec le grand défilé du Kadooment Day.', null, 'Crop Over fait désormais partie de ton carnet de route.', null),
    ('expedition-bb', 3, 'quiz', 'Défi de connaissances', 'Quelle récolte le festival Crop Over célébrait-il à l''origine ?', null, array['La canne à sucre', 'Le café', 'Le cacao', 'La banane']::text[], 'Crop Over marquait la fin de la récolte de la canne à sucre.', 0),
    ('expedition-bz', 1, 'locate', 'Situer le Belize', 'Le Belize se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Belmopan', 'Basseterre', 'Bridgetown', 'Castries']::text[], 'Belmopan est la capitale du Belize.', 0),
    ('expedition-bz', 2, 'discover', 'Découvrir : Grand Trou bleu', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Gouffre sous-marin circulaire au milieu d''un atoll, célèbre auprès des plongeurs. Il fait partie du réseau de réserves du récif de la barrière du Belize, inscrit à l''UNESCO.', null, 'Grand Trou bleu fait désormais partie de ton carnet de route.', null),
    ('expedition-bz', 3, 'quiz', 'Défi de connaissances', 'Quelle est la langue officielle du Belize ?', null, array['L''anglais', 'L''espagnol', 'Le français', 'Le portugais']::text[], 'Ancienne colonie britannique, le Belize a l''anglais pour langue officielle.', 0),
    ('expedition-cr', 1, 'locate', 'Situer le Costa Rica', 'Le Costa Rica se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Bridgetown', 'San José']::text[], 'San José est la capitale du Costa Rica.', 3),
    ('expedition-cr', 2, 'discover', 'Découvrir : Volcan Arenal', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Volcan au cône régulier qui domine un lac de barrage dans le nord du pays. Il a connu une longue période d''activité éruptive à partir de 1968.', null, 'Volcan Arenal fait désormais partie de ton carnet de route.', null),
    ('expedition-cr', 3, 'quiz', 'Défi de connaissances', 'Qu''a aboli le Costa Rica en 1948 ?', null, array['Sa monnaie', 'Sa monarchie', 'Son parlement', 'Son armée']::text[], 'Le Costa Rica a supprimé son armée en 1948.', 3),
    ('expedition-cu', 1, 'locate', 'Situer Cuba', 'Cuba se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'La Havane', 'Bridgetown']::text[], 'La Havane est la capitale de Cuba.', 2),
    ('expedition-cu', 2, 'discover', 'Découvrir : Vieille Havane', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Centre historique de La Havane aux places coloniales et aux façades colorées. Le Malecón, long boulevard en bord de mer, longe une partie de la ville.', null, 'Vieille Havane fait désormais partie de ton carnet de route.', null),
    ('expedition-cu', 3, 'quiz', 'Défi de connaissances', 'Quelle est la plus grande île des Caraïbes ?', null, array['Hispaniola', 'La Jamaïque', 'Cuba', 'Porto Rico']::text[], 'Cuba est la plus grande île des Caraïbes.', 2),
    ('expedition-dm', 1, 'locate', 'Situer la Dominique', 'La Dominique se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Roseau', 'Belmopan', 'Bridgetown']::text[], 'Roseau est la capitale de la Dominique.', 1),
    ('expedition-dm', 2, 'discover', 'Découvrir : Boiling Lake', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Lac volcanique dont l''eau bouillonne sous l''effet de la chaleur souterraine. Il se trouve dans un parc national inscrit au patrimoine mondial de l''UNESCO.', null, 'Boiling Lake fait désormais partie de ton carnet de route.', null),
    ('expedition-dm', 3, 'quiz', 'Défi de connaissances', 'Quel est le surnom de la Dominique ?', null, array['L''île aux fleurs', 'L''île nature', 'L''île de beauté', 'L''île aux épices']::text[], 'La Dominique est surnommée « l''île nature ».', 1),
    ('expedition-gd', 1, 'locate', 'Situer la Grenade', 'La Grenade se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Saint-Georges', 'Belmopan', 'Bridgetown']::text[], 'Saint-Georges est la capitale de la Grenade.', 1),
    ('expedition-gd', 2, 'discover', 'Découvrir : Noix de muscade', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Épice cultivée sur l''île, qui en a fait l''un de ses symboles. Une noix de muscade figure sur le drapeau national.', null, 'Noix de muscade fait désormais partie de ton carnet de route.', null),
    ('expedition-gd', 3, 'quiz', 'Défi de connaissances', 'Quelle épice figure sur le drapeau de la Grenade ?', null, array['La cannelle', 'La noix de muscade', 'Le clou de girofle', 'La vanille']::text[], 'La noix de muscade, emblème de l''île, figure sur le drapeau.', 1),
    ('expedition-gt', 1, 'locate', 'Situer le Guatemala', 'Le Guatemala se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Basseterre', 'Guatemala', 'Belmopan', 'Bridgetown']::text[], 'Guatemala est la capitale du Guatemala.', 1),
    ('expedition-gt', 2, 'discover', 'Découvrir : Tikal', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Grande cité maya en ruine au cœur de la forêt tropicale du Petén. Ses temples-pyramides dépassent la canopée de la forêt.', null, 'Tikal fait désormais partie de ton carnet de route.', null),
    ('expedition-gt', 3, 'quiz', 'Défi de connaissances', 'Quelle civilisation a bâti la cité de Tikal ?', null, array['Les Aztèques', 'Les Mayas', 'Les Incas', 'Les Olmèques']::text[], 'Tikal est l''une des grandes cités de la civilisation maya.', 1),
    ('expedition-ht', 1, 'locate', 'Situer Haïti', 'Haïti se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Port-au-Prince', 'Basseterre', 'Belmopan', 'Bridgetown']::text[], 'Port-au-Prince est la capitale d''Haïti.', 0),
    ('expedition-ht', 2, 'discover', 'Découvrir : Citadelle Laferrière', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forteresse construite au sommet d''une montagne au début du XIXe siècle, après l''indépendance. Elle fait partie du Parc national historique inscrit au patrimoine mondial de l''UNESCO.', null, 'Citadelle Laferrière fait désormais partie de ton carnet de route.', null),
    ('expedition-ht', 3, 'quiz', 'Défi de connaissances', 'En quelle année Haïti a-t-elle proclamé son indépendance ?', null, array['1804', '1789', '1848', '1902']::text[], 'Haïti a proclamé son indépendance le 1er janvier 1804.', 0),
    ('expedition-hn', 1, 'locate', 'Situer le Honduras', 'Le Honduras se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Tegucigalpa', 'Bridgetown']::text[], 'Tegucigalpa est la capitale du Honduras.', 2),
    ('expedition-hn', 2, 'discover', 'Découvrir : Copán', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cité maya réputée pour ses stèles et son escalier hiéroglyphique. Le site est inscrit au patrimoine mondial de l''UNESCO depuis 1980.', null, 'Copán fait désormais partie de ton carnet de route.', null),
    ('expedition-hn', 3, 'quiz', 'Défi de connaissances', 'Quel célèbre site maya se trouve au Honduras ?', null, array['Tikal', 'Palenque', 'Copán', 'Chichén Itzá']::text[], 'Copán se trouve dans l''ouest du Honduras.', 2),
    ('expedition-jm', 1, 'locate', 'Situer la Jamaïque', 'La Jamaïque se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Bridgetown', 'Kingston']::text[], 'Kingston est la capitale de la Jamaïque.', 3),
    ('expedition-jm', 2, 'discover', 'Découvrir : Reggae', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Genre musical né en Jamaïque à la fin des années 1960. La musique reggae de Jamaïque est inscrite au patrimoine culturel immatériel de l''UNESCO depuis 2018.', null, 'Reggae fait désormais partie de ton carnet de route.', null),
    ('expedition-jm', 3, 'quiz', 'Défi de connaissances', 'Quel genre musical est né en Jamaïque ?', null, array['La salsa', 'La samba', 'Le tango', 'Le reggae']::text[], 'Le reggae est apparu en Jamaïque à la fin des années 1960.', 3),
    ('expedition-ni', 1, 'locate', 'Situer le Nicaragua', 'Le Nicaragua se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Bridgetown', 'Managua']::text[], 'Managua est la capitale du Nicaragua.', 3),
    ('expedition-ni', 2, 'discover', 'Découvrir : Ruines de León Viejo', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vestiges de l''une des plus anciennes villes coloniales espagnoles des Amériques. Abandonnée au XVIIe siècle, elle est inscrite au patrimoine mondial de l''UNESCO.', null, 'Ruines de León Viejo fait désormais partie de ton carnet de route.', null),
    ('expedition-ni', 3, 'quiz', 'Défi de connaissances', 'Quel est le plus grand lac d''Amérique centrale ?', null, array['Le lac Atitlán', 'Le lac Titicaca', 'Le lac de Managua', 'Le lac Cocibolca']::text[], 'Le lac Cocibolca, ou lac Nicaragua, est le plus grand d''Amérique centrale.', 3),
    ('expedition-pa', 1, 'locate', 'Situer le Panama', 'Le Panama se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Basseterre', 'Panama', 'Belmopan', 'Bridgetown']::text[], 'Panama est la capitale du Panama.', 1),
    ('expedition-pa', 2, 'discover', 'Découvrir : Canal de Panama', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Voie navigable d''environ 80 kilomètres inaugurée en 1914. Des écluses font monter et descendre les navires pour franchir l''isthme.', null, 'Canal de Panama fait désormais partie de ton carnet de route.', null),
    ('expedition-pa', 3, 'quiz', 'Défi de connaissances', 'Quels océans le canal de Panama relie-t-il ?', null, array['L''Atlantique et l''Indien', 'L''Atlantique et le Pacifique', 'Le Pacifique et l''Arctique', 'L''Indien et le Pacifique']::text[], 'Le canal de Panama relie l''Atlantique, via la mer des Caraïbes, au Pacifique.', 1),
    ('expedition-do', 1, 'locate', 'Situer la République dominicaine', 'La République dominicaine se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Bridgetown', 'Saint-Domingue']::text[], 'Saint-Domingue est la capitale de la République dominicaine.', 3),
    ('expedition-do', 2, 'discover', 'Découvrir : Merengue', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Musique et danse de couple au rythme rapide, emblèmes du pays. Le merengue dominicain est inscrit au patrimoine culturel immatériel de l''UNESCO depuis 2016.', null, 'Merengue fait désormais partie de ton carnet de route.', null),
    ('expedition-do', 3, 'quiz', 'Défi de connaissances', 'Avec quel pays la République dominicaine partage-t-elle son île ?', null, array['Cuba', 'La Jamaïque', 'Porto Rico', 'Haïti']::text[], 'Haïti et la République dominicaine se partagent l''île d''Hispaniola.', 3),
    ('expedition-kn', 1, 'locate', 'Situer Saint-Christophe-et-Niévès', 'Saint-Christophe-et-Niévès se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Belmopan', 'Bridgetown', 'Castries', 'Basseterre']::text[], 'Basseterre est la capitale de Saint-Christophe-et-Niévès.', 3),
    ('expedition-kn', 2, 'discover', 'Découvrir : Forteresse de Brimstone Hill', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Forteresse britannique des XVIIe et XVIIIe siècles perchée sur une colline volcanique. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 1999.', null, 'Forteresse de Brimstone Hill fait désormais partie de ton carnet de route.', null),
    ('expedition-kn', 3, 'quiz', 'Défi de connaissances', 'Quel autre nom donne-t-on à l''île de Saint-Christophe ?', null, array['Sainte-Lucie', 'Saint-Vincent', 'Saint-Martin', 'Saint-Kitts']::text[], 'Saint-Christophe est aussi connue sous le nom de Saint-Kitts.', 3),
    ('expedition-vc', 1, 'locate', 'Situer Saint-Vincent-et-les-Grenadines', 'Saint-Vincent-et-les-Grenadines se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Kingstown', 'Belmopan', 'Bridgetown']::text[], 'Kingstown est la capitale de Saint-Vincent-et-les-Grenadines.', 1),
    ('expedition-vc', 2, 'discover', 'Découvrir : La Soufrière', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Volcan actif qui occupe le nord de l''île de Saint-Vincent. C''est le point culminant du pays.', null, 'La Soufrière fait désormais partie de ton carnet de route.', null),
    ('expedition-vc', 3, 'quiz', 'Défi de connaissances', 'Quel volcan de Saint-Vincent est entré en éruption en 2021 ?', null, array['La Montagne Pelée', 'La Soufrière', 'Le Piton de la Fournaise', 'Le Popocatépetl']::text[], 'La Soufrière de Saint-Vincent est entrée en éruption en avril 2021.', 1),
    ('expedition-lc', 1, 'locate', 'Situer Sainte-Lucie', 'Sainte-Lucie se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Bridgetown', 'Castries']::text[], 'Castries est la capitale de Sainte-Lucie.', 3),
    ('expedition-lc', 2, 'discover', 'Découvrir : Pitons', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Deux pics volcaniques qui s''élèvent directement depuis la mer. La zone protégée des Pitons est inscrite au patrimoine mondial de l''UNESCO.', null, 'Pitons fait désormais partie de ton carnet de route.', null),
    ('expedition-lc', 3, 'quiz', 'Défi de connaissances', 'Comment s''appellent les deux pics volcaniques de Sainte-Lucie ?', null, array['Les Mamelles', 'Les Dents', 'Les Jumeaux', 'Les Pitons']::text[], 'Les Pitons, Gros Piton et Petit Piton, dominent la côte sud-ouest.', 3),
    ('expedition-sv', 1, 'locate', 'Situer le Salvador', 'Le Salvador se trouve en Amérique du Nord (Amérique centrale). Quelle est sa capitale ?', null, array['Basseterre', 'Belmopan', 'Bridgetown', 'San Salvador']::text[], 'San Salvador est la capitale du Salvador.', 3),
    ('expedition-sv', 2, 'discover', 'Découvrir : Joya de Cerén', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Village maya enseveli sous les cendres d''une éruption vers le VIIe siècle. Ce site exceptionnellement conservé est inscrit au patrimoine mondial de l''UNESCO.', null, 'Joya de Cerén fait désormais partie de ton carnet de route.', null),
    ('expedition-sv', 3, 'quiz', 'Défi de connaissances', 'Sur quel océan le Salvador est-il ouvert ?', null, array['L''océan Atlantique', 'La mer des Caraïbes', 'L''océan Indien', 'L''océan Pacifique']::text[], 'Le Salvador est le seul pays d''Amérique centrale sans façade caraïbe.', 3),
    ('expedition-tt', 1, 'locate', 'Situer Trinité-et-Tobago', 'Trinité-et-Tobago se trouve en Amérique du Nord (Caraïbes). Quelle est sa capitale ?', null, array['Port-d''Espagne', 'Basseterre', 'Belmopan', 'Bridgetown']::text[], 'Port-d''Espagne est la capitale de Trinité-et-Tobago.', 0),
    ('expedition-tt', 2, 'discover', 'Découvrir : Steelpan', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Instrument de percussion accordé, façonné à partir de bidons d''huile en acier. Il est né à Trinité au milieu du XXe siècle.', null, 'Steelpan fait désormais partie de ton carnet de route.', null),
    ('expedition-tt', 3, 'quiz', 'Défi de connaissances', 'Quel instrument est né à Trinité-et-Tobago ?', null, array['Le steelpan', 'Le ukulélé', 'Le bandonéon', 'Le djembé']::text[], 'Le steelpan est fabriqué à partir de bidons d''acier.', 0),
    ('expedition-bo', 1, 'locate', 'Situer la Bolivie', 'La Bolivie se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Asuncion', 'Sucre', 'Bogota', 'Brasília']::text[], 'Sucre est la capitale de la Bolivie.', 1),
    ('expedition-bo', 2, 'discover', 'Découvrir : Salar d''Uyuni', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Immense étendue de sel sur l''Altiplano andin. C''est le plus grand désert de sel du monde.', null, 'Salar d''Uyuni fait désormais partie de ton carnet de route.', null),
    ('expedition-bo', 3, 'quiz', 'Défi de connaissances', 'Comment s''appelle le plus grand désert de sel du monde, en Bolivie ?', null, array['Le salar d''Atacama', 'Le salar d''Uyuni', 'Le Chott el-Jérid', 'Le lac Salé']::text[], 'Le salar d''Uyuni s''étend sur l''Altiplano bolivien.', 1),
    ('expedition-co', 1, 'locate', 'Situer la Colombie', 'La Colombie se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Bogota', 'Asuncion', 'Brasília', 'Buenos Aires']::text[], 'Bogota est la capitale de la Colombie.', 0),
    ('expedition-co', 2, 'discover', 'Découvrir : Carthagène des Indes', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Port colonial fortifié sur la mer des Caraïbes. Ses remparts et sa vieille ville sont inscrits au patrimoine mondial de l''UNESCO.', null, 'Carthagène des Indes fait désormais partie de ton carnet de route.', null),
    ('expedition-co', 3, 'quiz', 'Défi de connaissances', 'Quelle est la particularité littorale de la Colombie en Amérique du Sud ?', null, array['Elle borde les Caraïbes et le Pacifique', 'Elle n''a aucun littoral', 'Elle borde seulement l''Atlantique', 'Elle borde l''océan Indien']::text[], 'La Colombie est le seul pays sud-américain ouvert sur les Caraïbes et le Pacifique.', 0),
    ('expedition-gy', 1, 'locate', 'Situer le Guyana', 'Le Guyana se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Asuncion', 'Bogota', 'Georgetown', 'Brasília']::text[], 'Georgetown est la capitale du Guyana.', 2),
    ('expedition-gy', 2, 'discover', 'Découvrir : Chutes de Kaieteur', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Chute d''eau spectaculaire au cœur de la forêt tropicale. Elle compte parmi les plus hautes chutes à un seul saut du monde.', null, 'Chutes de Kaieteur fait désormais partie de ton carnet de route.', null),
    ('expedition-gy', 3, 'quiz', 'Défi de connaissances', 'Quelle est la langue officielle du Guyana ?', null, array['L''espagnol', 'Le néerlandais', 'L''anglais', 'Le portugais']::text[], 'Ancienne colonie britannique, le Guyana a l''anglais pour langue officielle.', 2),
    ('expedition-py', 1, 'locate', 'Situer le Paraguay', 'Le Paraguay se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Bogota', 'Asuncion', 'Brasília', 'Buenos Aires']::text[], 'Asuncion est la capitale du Paraguay.', 1),
    ('expedition-py', 2, 'discover', 'Découvrir : Missions jésuites', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vestiges de missions fondées par les jésuites auprès des Guaranis aux XVIIe et XVIIIe siècles. Les missions de La Santísima Trinidad de Paraná et de Jesús de Tavarangue sont inscrites à l''UNESCO.', null, 'Missions jésuites fait désormais partie de ton carnet de route.', null),
