    ('expedition-sr', 1, 'locate', 'Situer le Suriname', 'Le Suriname se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Asuncion', 'Bogota', 'Brasília', 'Paramaribo']::text[], 'Paramaribo est la capitale du Suriname.', 3),
    ('expedition-sr', 2, 'discover', 'Découvrir : Réserve naturelle du Suriname central', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vaste zone de forêt tropicale intacte au cœur du pays. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2000.', null, 'Réserve naturelle du Suriname central fait désormais partie de ton carnet de route.', null),
    ('expedition-sr', 3, 'quiz', 'Défi de connaissances', 'Quelle est la langue officielle du Suriname ?', null, array['L''anglais', 'Le français', 'L''espagnol', 'Le néerlandais']::text[], 'Ancienne colonie néerlandaise, le Suriname a le néerlandais pour langue officielle.', 3),
    ('expedition-uy', 1, 'locate', 'Situer l''Uruguay', 'L''Uruguay se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Montevideo', 'Asuncion', 'Bogota', 'Brasília']::text[], 'Montevideo est la capitale de l''Uruguay.', 0),
    ('expedition-uy', 2, 'discover', 'Découvrir : Colonia del Sacramento', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ville fondée par les Portugais en 1680 sur le Río de la Plata. Son quartier historique est inscrit au patrimoine mondial de l''UNESCO.', null, 'Colonia del Sacramento fait désormais partie de ton carnet de route.', null),
    ('expedition-uy', 3, 'quiz', 'Défi de connaissances', 'Quel pays a remporté la première Coupe du monde de football en 1930 ?', null, array['L''Uruguay', 'Le Brésil', 'L''Argentine', 'L''Italie']::text[], 'L''Uruguay a organisé et remporté la première Coupe du monde en 1930.', 0),
    ('expedition-ve', 1, 'locate', 'Situer le Venezuela', 'Le Venezuela se trouve en Amérique du Sud (Amérique du Sud). Quelle est sa capitale ?', null, array['Asuncion', 'Bogota', 'Brasília', 'Caracas']::text[], 'Caracas est la capitale du Venezuela.', 3),
    ('expedition-ve', 2, 'discover', 'Découvrir : Salto Ángel', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Chute d''eau qui tombe du sommet d''un tepui, plateau aux parois verticales. C''est la plus haute chute d''eau du monde, avec environ 979 mètres.', null, 'Salto Ángel fait désormais partie de ton carnet de route.', null),
    ('expedition-ve', 3, 'quiz', 'Défi de connaissances', 'Quelle est la plus haute chute d''eau du monde ?', null, array['Les chutes Victoria', 'Les chutes d''Iguaçu', 'Les chutes du Niagara', 'Le Salto Ángel']::text[], 'Le Salto Ángel, au Venezuela, atteint environ 979 mètres.', 3),
