    ('expedition-fj', 2, 'discover', 'Découvrir : Levuka', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ancien port colonial et première capitale des Fidji sous administration britannique. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2013.', null, 'Levuka fait désormais partie de ton carnet de route.', null),
    ('expedition-fj', 3, 'quiz', 'Défi de connaissances', 'Quel sport a valu aux Fidji leur première médaille d''or olympique ?', null, array['Le rugby à sept', 'La natation', 'L''aviron', 'La boxe']::text[], 'L''équipe fidjienne de rugby à sept a été sacrée en 2016.', 0),
