    ('expedition-ki', 2, 'discover', 'Découvrir : Aire protégée des îles Phoenix', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vaste aire marine protégée autour d''atolls isolés. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2010.', null, 'Aire protégée des îles Phoenix fait désormais partie de ton carnet de route.', null),
    ('expedition-ki', 3, 'quiz', 'Défi de connaissances', 'Quelle ligne imaginaire traverse les îles de Kiribati ?', null, array['Le tropique du Cancer', 'Le cercle polaire', 'L''équateur', 'Le méridien de Greenwich']::text[], 'Les atolls de Kiribati sont dispersés de part et d''autre de l''équateur.', 2),
    ('expedition-fm', 1, 'locate', 'Situer la Micronésie', 'La Micronésie se trouve en Océanie (Micronésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Palikir']::text[], 'Palikir est la capitale de la Micronésie.', 3),
    ('expedition-fm', 2, 'discover', 'Découvrir : Nan Madol', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Cité de blocs de basalte bâtie sur des îlots artificiels. Elle est inscrite au patrimoine mondial de l''UNESCO depuis 2016.', null, 'Nan Madol fait désormais partie de ton carnet de route.', null),
    ('expedition-fm', 3, 'quiz', 'Défi de connaissances', 'Sur quoi la cité de Nan Madol est-elle bâtie ?', null, array['Un volcan', 'Une falaise', 'Un glacier', 'Des îlots artificiels']::text[], 'Nan Madol est construite sur une centaine d''îlots artificiels.', 3),
    ('expedition-nr', 1, 'locate', 'Situer Nauru', 'Nauru se trouve en Océanie (Micronésie). Quelle est sa capitale ?', null, array['Yaren', 'Alofi', 'Apia', 'Avarua']::text[], 'Yaren est la capitale de Nauru.', 0),
    ('expedition-nr', 2, 'discover', 'Découvrir : Plateau central de Nauru', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Plateau intérieur appelé « Topside », largement exploité pour son phosphate. L''extraction a laissé un paysage de pitons de corail.', null, 'Plateau central de Nauru fait désormais partie de ton carnet de route.', null),
    ('expedition-nr', 3, 'quiz', 'Défi de connaissances', 'Quelle ressource a longtemps fait vivre Nauru ?', null, array['Le phosphate', 'Le pétrole', 'L''or', 'Le cuivre']::text[], 'L''extraction du phosphate a longtemps dominé l''économie de Nauru.', 0),
    ('expedition-nu', 1, 'locate', 'Situer Niue', 'Niue se trouve en Océanie (Polynésie). Quelle est sa capitale ?', null, array['Apia', 'Avarua', 'Canberra', 'Alofi']::text[], 'Alofi est la capitale de Niue.', 3),
    ('expedition-nu', 2, 'discover', 'Découvrir : Arches de Talava', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Arches de calcaire sculptées par la mer sur la côte rocheuse. Elles font partie des nombreuses grottes et criques de l''île.', null, 'Arches de Talava fait désormais partie de ton carnet de route.', null),
    ('expedition-nu', 3, 'quiz', 'Défi de connaissances', 'Quel est le surnom de Niue ?', null, array['L''île aux trésors', 'La perle du Pacifique', 'L''île de Pâques', 'Le rocher de Polynésie']::text[], 'Niue est surnommée « le rocher de Polynésie ».', 3),
    ('expedition-pw', 1, 'locate', 'Situer les Palaos', 'Les Palaos se trouve en Océanie (Micronésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Ngerulmud']::text[], 'Ngerulmud est la capitale des Palaos.', 3),
    ('expedition-pw', 2, 'discover', 'Découvrir : Rock Islands', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Centaines d''îlots calcaires couverts de forêt, en forme de champignon. Le lagon sud des Rock Islands est inscrit au patrimoine mondial de l''UNESCO depuis 2012.', null, 'Rock Islands fait désormais partie de ton carnet de route.', null),
    ('expedition-pw', 3, 'quiz', 'Défi de connaissances', 'Quel sanctuaire les Palaos ont-ils créé en 2009 ?', null, array['Un sanctuaire d''oiseaux', 'Un sanctuaire de tortues', 'Un sanctuaire de baleines', 'Un sanctuaire de requins']::text[], 'Les Palaos ont interdit la pêche commerciale des requins dans leurs eaux.', 3),
    ('expedition-pg', 1, 'locate', 'Situer la Papouasie-Nouvelle-Guinée', 'La Papouasie-Nouvelle-Guinée se trouve en Océanie (Mélanésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Port Moresby']::text[], 'Port Moresby est la capitale de la Papouasie-Nouvelle-Guinée.', 3),
    ('expedition-pg', 2, 'discover', 'Découvrir : Site agricole ancien de Kuk', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Zone humide où l''on a retrouvé des traces d''agriculture très anciennes. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2008.', null, 'Site agricole ancien de Kuk fait désormais partie de ton carnet de route.', null),
    ('expedition-pg', 3, 'quiz', 'Défi de connaissances', 'Combien de langues parle-t-on environ en Papouasie-Nouvelle-Guinée ?', null, array['Une vingtaine', 'Environ 100', 'Environ 300', 'Plus de 800']::text[], 'La Papouasie-Nouvelle-Guinée détient le record mondial de diversité linguistique.', 3),
