    ('expedition-ws', 2, 'discover', 'Découvrir : To Sua', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Bassin naturel au fond d''un effondrement, relié à l''océan. On y descend par une longue échelle de bois.', null, 'To Sua fait désormais partie de ton carnet de route.', null),
    ('expedition-ws', 3, 'quiz', 'Défi de connaissances', 'Quel écrivain a vécu ses dernières années aux Samoa ?', null, array['Robert Louis Stevenson', 'Jack London', 'Herman Melville', 'Paul Gauguin']::text[], 'L''auteur de L''Île au trésor a vécu près d''Apia.', 0),
    ('expedition-to', 1, 'locate', 'Situer Tonga', 'Tonga se trouve en Océanie (Polynésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Nuku''alofa']::text[], 'Nuku''alofa est la capitale de Tonga.', 3),
    ('expedition-to', 2, 'discover', 'Découvrir : Ha''amonga ''a Maui', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Trilithe de corail formé de deux piliers et d''un linteau. Il aurait été érigé vers le XIIIe siècle.', null, 'Ha''amonga ''a Maui fait désormais partie de ton carnet de route.', null),
    ('expedition-to', 3, 'quiz', 'Défi de connaissances', 'Quel est le régime politique des Tonga ?', null, array['Une république', 'Un émirat', 'Une théocratie', 'Une monarchie']::text[], 'Les Tonga sont la seule monarchie du Pacifique insulaire.', 3),
    ('expedition-tv', 1, 'locate', 'Situer Tuvalu', 'Tuvalu se trouve en Océanie (Polynésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Funafuti', 'Avarua']::text[], 'Funafuti est la capitale de Tuvalu.', 2),
    ('expedition-tv', 2, 'discover', 'Découvrir : Lagon de Funafuti', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Vaste lagon bordé d''îlots, dont une partie est classée en aire de conservation. Il abrite tortues, poissons de récif et oiseaux marins.', null, 'Lagon de Funafuti fait désormais partie de ton carnet de route.', null),
    ('expedition-tv', 3, 'quiz', 'Défi de connaissances', 'Pourquoi Tuvalu est-il très exposé à la montée des eaux ?', null, array['Il est situé sur un volcan', 'Il est sous la banquise', 'Ses îles sont très basses', 'Il est traversé par un fleuve']::text[], 'Les îles de Tuvalu culminent à quelques mètres seulement.', 2),
    ('expedition-vu', 1, 'locate', 'Situer le Vanuatu', 'Le Vanuatu se trouve en Océanie (Mélanésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Port-Vila']::text[], 'Port-Vila est la capitale du Vanuatu.', 3),
    ('expedition-vu', 2, 'discover', 'Découvrir : Domaine du chef Roi Mata', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Ensemble de sites liés à la vie et à la sépulture d''un chef du début du XVIIe siècle. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2008.', null, 'Domaine du chef Roi Mata fait désormais partie de ton carnet de route.', null),
    ('expedition-vu', 3, 'quiz', 'Défi de connaissances', 'Quelles langues sont officielles au Vanuatu ?', null, array['Anglais seulement', 'Français et espagnol', 'Anglais et maori', 'Français, anglais et bichelamar']::text[], 'Ancien condominium franco-britannique, le Vanuatu a trois langues officielles.', 3),
    ('expedition-ck', 1, 'locate', 'Situer les Îles Cook', 'Les Îles Cook se trouve en Océanie (Polynésie). Quelle est sa capitale ?', null, array['Avarua', 'Alofi', 'Apia', 'Canberra']::text[], 'Avarua est la capitale des Îles Cook.', 0),
    ('expedition-ck', 2, 'discover', 'Découvrir : Lagon d''Aitutaki', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Lagon turquoise parsemé d''îlots, entouré d''une barrière de corail. Une petite île volcanique domine ce lagon fermé par un récif corallien.', null, 'Lagon d''Aitutaki fait désormais partie de ton carnet de route.', null),
    ('expedition-ck', 3, 'quiz', 'Défi de connaissances', 'Avec quel pays les îles Cook sont-elles librement associées ?', null, array['La Nouvelle-Zélande', 'L''Australie', 'Le Royaume-Uni', 'Les États-Unis']::text[], 'Les îles Cook sont librement associées à la Nouvelle-Zélande.', 0),
    ('expedition-mh', 1, 'locate', 'Situer les Îles Marshall', 'Les Îles Marshall se trouve en Océanie (Micronésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Majuro']::text[], 'Majuro est la capitale des Îles Marshall.', 3),
    ('expedition-mh', 2, 'discover', 'Découvrir : Atoll de Bikini', 'Prends le temps de lire cette découverte, puis poursuis ton expédition.', 'Atoll où les États-Unis ont mené des essais nucléaires de 1946 à 1958. Il est inscrit au patrimoine mondial de l''UNESCO depuis 2010.', null, 'Atoll de Bikini fait désormais partie de ton carnet de route.', null),
    ('expedition-mh', 3, 'quiz', 'Défi de connaissances', 'Quels essais ont eu lieu sur l''atoll de Bikini ?', null, array['Des essais de fusées', 'Des essais de sous-marins', 'Des essais d''avions', 'Des essais nucléaires']::text[], 'Les États-Unis y ont mené des essais nucléaires de 1946 à 1958.', 3),
    ('expedition-sb', 1, 'locate', 'Situer les Îles Salomon', 'Les Îles Salomon se trouve en Océanie (Mélanésie). Quelle est sa capitale ?', null, array['Alofi', 'Apia', 'Avarua', 'Honiara']::text[], 'Honiara est la capitale des Îles Salomon.', 3),
